-- Proposed native retention append only. No terminal or source-completeness credit.

set local lock_timeout='5s';

set local statement_timeout='60s';

do $$ begin
if to_regclass('ingestion_generation_evidence.managed_vector_chunk_rows') is not null then raise exception 'native_append_existing_table_managed_vector_chunk_rows'; end if;
if to_regclass('ingestion_generation_evidence.managed_vector_field_rows') is not null then raise exception 'native_append_existing_table_managed_vector_field_rows'; end if;
if to_regclass('ingestion_generation_evidence.managed_vector_index_rows') is not null then raise exception 'native_append_existing_table_managed_vector_index_rows'; end if;
if to_regclass('ingestion_generation_evidence.managed_vector_final_receipts') is not null then raise exception 'native_append_existing_table_managed_vector_final_receipts'; end if;
if to_regclass('ingestion_generation_evidence.scoped_projection_artifacts') is not null then raise exception 'native_append_existing_table_scoped_projection_artifacts'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='managed_vector_artifact') then raise exception 'native_append_existing_function_managed_vector_artifact'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='validate_native_parent_closure') then raise exception 'native_append_existing_function_validate_native_parent_closure'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='native_parent_closure_bundle') then raise exception 'native_append_existing_function_native_parent_closure_bundle'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='read_native_parent_closure') then raise exception 'native_append_existing_function_read_native_parent_closure'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='stage_native_parent_closure') then raise exception 'native_append_existing_function_stage_native_parent_closure'; end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.write_ingestion_base_artifacts(jsonb,uuid,jsonb,jsonb,jsonb,jsonb,jsonb)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'native_append_preimage_write_ingestion_base_artifacts'; end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.read_ingestion_prepared_supplier_artifacts(jsonb,uuid)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'native_append_preimage_read_ingestion_prepared_supplier_artifacts'; end if;
end $$;

create table ingestion_generation_evidence.managed_vector_chunk_rows (
  like public.document_chunks including defaults including constraints including generated,
  packet_identity jsonb not null,prepared_sha256 text not null,
  primary key(id),unique(document_id,index_generation_id,chunk_index),
  foreign key(document_id,index_generation_id) references ingestion_generation_evidence.managed_vector_packets(document_id,generation_id)
);

create table ingestion_generation_evidence.managed_vector_field_rows (
  like public.document_embedding_fields including defaults including constraints including generated,
  packet_identity jsonb not null,prepared_sha256 text not null,
  primary key(id),
  foreign key(document_id,index_generation_id) references ingestion_generation_evidence.managed_vector_packets(document_id,generation_id)
);

create table ingestion_generation_evidence.managed_vector_index_rows (
  like public.document_index_units including defaults including constraints including generated,
  packet_identity jsonb not null,prepared_sha256 text not null,
  primary key(id),
  foreign key(document_id,index_generation_id) references ingestion_generation_evidence.managed_vector_packets(document_id,generation_id)
);

create table ingestion_generation_evidence.managed_vector_final_receipts (
  document_id uuid not null,generation_id uuid not null,family text not null,row_id uuid not null,
  artifact_bytes bytea not null,sha256 text not null,byte_length bigint not null,
  primary key(document_id,generation_id,family,row_id),
  foreign key(document_id,generation_id) references ingestion_generation_evidence.managed_vector_packets,
  check(family in ('chunks','embedding_fields','index_units')),
  check(byte_length=octet_length(artifact_bytes)),
  check(sha256='sha256:'||encode(extensions.digest(artifact_bytes,'sha256'),'hex'))
);

create table ingestion_generation_evidence.scoped_projection_artifacts (
 document_id uuid not null,generation_id uuid not null,projection_id uuid not null,
 family text not null check(family in ('images','chunks','table_facts')),row_id uuid not null,
 phase text not null check(phase in ('prepared','final')),artifact_bytes bytea not null,sha256 text not null,byte_length bigint not null,
 primary key(document_id,generation_id,projection_id,family,row_id,phase),
 foreign key(document_id,generation_id,projection_id) references ingestion_generation_evidence.scoped_projection_expectations,
 check(byte_length=octet_length(artifact_bytes) and byte_length between 1 and 2097152),
 check(sha256='sha256:'||encode(extensions.digest(artifact_bytes,'sha256'),'hex'))
);

do $$ declare t text;begin
  foreach t in array array['managed_vector_chunk_rows','managed_vector_field_rows','managed_vector_index_rows'] loop
    execute format('alter table ingestion_generation_evidence.%I alter column index_generation_id set not null',t);
  end loop;
  foreach t in array array['managed_vector_chunk_rows','managed_vector_field_rows','managed_vector_index_rows','managed_vector_final_receipts','scoped_projection_artifacts'] loop
    execute format('alter table ingestion_generation_evidence.%I owner to postgres',t);
    execute format('alter table ingestion_generation_evidence.%I enable row level security',t);
    execute format('revoke all on ingestion_generation_evidence.%I from public,anon,authenticated,service_role',t);
    execute format('create trigger evidence_immutable before update or delete on ingestion_generation_evidence.%I for each row execute function ingestion_generation_evidence.immutable()',t);
    execute format('create trigger evidence_no_truncate before truncate on ingestion_generation_evidence.%I for each statement execute function ingestion_generation_evidence.immutable()',t);
  end loop;
end $$;

create function ingestion_generation_evidence.managed_vector_artifact(c ingestion_generation_evidence.candidates,p_unit jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare a ingestion_generation_evidence.retained_artifacts;u jsonb;g ingestion_generation_evidence.producer_declarations;o jsonb;
begin
  if not ingestion_generation_evidence.keys(p_unit,array['family','key']) then raise exception 'managed_vector_final_prepared_mismatch';end if;
  select * into a from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family=p_unit->>'family' and unit_key=p_unit->>'key';
  if not found then raise exception 'managed_vector_final_prepared_mismatch';end if;
  select declaration into u from ingestion_generation_evidence.unit_declarations where document_id=c.document_id and generation_id=c.generation_id and family=a.family and unit_key=a.unit_key and group_key=a.group_key;
  select * into g from ingestion_generation_evidence.producer_declarations where document_id=c.document_id and generation_id=c.generation_id and family=a.family and group_key=a.group_key;
  select outcome into o from ingestion_generation_evidence.outcomes where document_id=c.document_id and generation_id=c.generation_id and family=a.family and unit_key=a.unit_key and group_key=a.group_key;
  if u is null or g.document_id is null or g.first_lease_token is distinct from c.first_lease_token
    or u->'id' is distinct from p_unit or u->>'groupKey' is distinct from a.group_key or u->>'representation' is distinct from a.representation
    or a.source_sha256 is distinct from c.source_sha256 or a.byte_length is distinct from octet_length(a.artifact_bytes)::bigint
    or a.sha256 is distinct from 'sha256:'||encode(extensions.digest(a.artifact_bytes,'sha256'),'hex')
    or o is distinct from jsonb_build_object('unitId',p_unit,'groupKey',a.group_key,'disposition','retained','artifactSha256',a.sha256,'limitation',null)
    then raise exception 'managed_vector_final_prepared_mismatch';end if;
  return jsonb_build_object('declaration',u,'artifact',jsonb_build_object('unitId',p_unit,'groupKey',a.group_key,'representation',a.representation,
    'bytesHex',encode(a.artifact_bytes,'hex'),'sha256',a.sha256,'byteLength',a.byte_length,'locator',a.locator));
end $$;

alter function ingestion_generation_evidence.managed_vector_artifact(ingestion_generation_evidence.candidates,jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.managed_vector_artifact(ingestion_generation_evidence.candidates,jsonb) from public,anon,authenticated,service_role;

create function ingestion_generation_evidence.validate_native_parent_closure(c ingestion_generation_evidence.candidates,p_packet jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare
  j public.ingestion_jobs;issued jsonb;identity jsonb;claim jsonb;claim_body jsonb;orig jsonb;
  v_family text;g jsonb;ids jsonb;expected_ids jsonb:='[]'::jsonb;actual_ids jsonb;
  item jsonb;prepared jsonb;u jsonb;b jsonb;r jsonb;v extensions.vector(1536);text_input text;
  normalized jsonb:='[]'::jsonb;finished jsonb:='[]'::jsonb;parents jsonb;dep jsonb;pa jsonb;parent jsonb;links jsonb;k text;rec jsonb;x jsonb;
  cr public.document_chunks;fr public.document_embedding_fields;ir public.document_index_units;
  groups jsonb:='[]'::jsonb;manifest jsonb;manifest_bytes bytea;units jsonb;refs jsonb;provenance jsonb;capture jsonb;binary_art jsonb;table_md jsonb;image_row jsonb;chunk_row jsonb;facts jsonb;matched jsonb;semantic jsonb;declared_semantic jsonb;ord integer;total_table_rows integer:=0;page_count integer;
  pending jsonb;done jsonb:='[]'::jsonb;next_id jsonb;keys_expected text[];
begin
  if not ingestion_generation_evidence.keys(p_packet,array['version','planDigest','issued','rows','parents'])
    or p_packet->>'version' is distinct from 'managed-native-parent-closure-v1'
    or coalesce(p_packet->>'planDigest','') !~ '^sha256:[0-9a-f]{64}$'
    or jsonb_typeof(p_packet->'rows') is distinct from 'array' or jsonb_typeof(p_packet->'parents') is distinct from 'array'
    then raise exception 'managed_native_parent_closure_invalid_packet';end if;
  if octet_length(convert_to(p_packet::text,'UTF8'))>16777216 then raise exception 'managed_native_parent_closure_transport_limit';end if;
  if jsonb_array_length(p_packet->'rows')+jsonb_array_length(p_packet->'parents') not between 2 and 500 then raise exception 'managed_native_parent_closure_population_mismatch';end if;
  select * into strict j from public.ingestion_jobs where id=c.job_id;
  issued:=jsonb_build_object('documentId',c.document_id,'generationId',c.generation_id,'jobId',c.job_id,'workerId',case when j.status='completed' and c.source_sha256='sha256:abbc8107a09582e18f36bf4905c75f1fc78af70cd516851b89bff8919ca5bece' then
      (select convert_from(a.artifact_bytes,'UTF8')::jsonb->>'workerId' from ingestion_generation_evidence.retained_artifacts a
        where a.document_id=c.document_id and a.generation_id=c.generation_id and a.family='attempt_control' and a.unit_key='claim_checkpoint')
      else j.locked_by end,
    'firstLeaseToken',c.first_lease_token,'attemptNumber',j.attempt_count,'batchId',j.batch_id,'authorityDigest',c.authority_digest,'predecessorGenerationId',c.predecessor_generation_id);
  if p_packet->'issued' is distinct from issued or j.attempt_count<1
    or coalesce(c.source_snapshot->>'owner_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then raise exception 'managed_native_parent_closure_issued_mismatch';end if;
  identity:=issued||jsonb_build_object('ownerId',c.source_snapshot->'owner_id','sourceSha256',c.source_sha256,'sourceByteLength',c.source_byte_length,'sourceExpectationDigest',c.source_expectation_digest);
  claim:=ingestion_generation_evidence.managed_vector_artifact(c,'{"family":"attempt_control","key":"claim_checkpoint"}'::jsonb);
  claim_body:=convert_from(decode(claim->'artifact'->>'bytesHex','hex'),'UTF8')::jsonb;
  if claim_body is distinct from (issued||jsonb_build_object('version','ingestion-attempt-control-v1','phase','claim','qualification','derived_unverified',
      'sourceSha256',c.source_sha256,'sourceByteLength',c.source_byte_length,'sourceExpectationDigest',c.source_expectation_digest))
    or claim->'artifact'->>'locator' is distinct from 'ingestion_attempt:claim' or claim->'artifact'->>'representation' is distinct from 'provenance_json'
    then raise exception 'managed_native_parent_closure_issued_mismatch';end if;
  orig:=ingestion_generation_evidence.managed_vector_artifact(c,'{"family":"private_objects","key":"original-source"}'::jsonb);
  if orig->'artifact'->>'sha256' is distinct from c.source_sha256 or orig->'artifact'->'byteLength' is distinct from to_jsonb(c.source_byte_length)
    or orig->'artifact'->>'representation' is distinct from 'original_binary' then raise exception 'managed_native_parent_closure_prepared_mismatch';end if;
  foreach v_family in array array['chunks','embedding_fields','images','index_units','table_facts'] loop
    select declaration into g from ingestion_generation_evidence.producer_declarations where document_id=c.document_id and generation_id=c.generation_id and producer_declarations.family=v_family and group_key='worker_core' and first_lease_token=c.first_lease_token;
    if g is null or g->'population'->>'tag' is distinct from 'known' or jsonb_typeof(g->'population'->'expectedUnits') is distinct from 'array'
      or g->'artifactGenerationId' is distinct from 'null'::jsonb
      or g->'producer'->>'name' is distinct from 'managed-local-prepared-'||v_family
      or g->'producer'->>'version' is distinct from 'managed-private-preparation-v1' then raise exception 'managed_native_parent_closure_population_mismatch';end if;
    ids:=g->'population'->'expectedUnits';
    if (jsonb_array_length(ids)=0 and g->'population'->>'reason' is distinct from 'no_units_expected') or (jsonb_array_length(ids)>0 and g->'population'->'reason' is distinct from 'null'::jsonb) then raise exception 'managed_native_parent_closure_population_mismatch';end if;
    if exists(select 1 from jsonb_array_elements(ids) a where not ingestion_generation_evidence.keys(a.value,array['family','key']) or a.value->>'family' is distinct from v_family or coalesce(a.value->>'key','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
      or jsonb_array_length(ids)<>(select count(distinct a.value) from jsonb_array_elements(ids) a)
      or (select coalesce(jsonb_agg(d.declaration->'id' order by d.unit_key),'[]'::jsonb) from ingestion_generation_evidence.unit_declarations d where d.document_id=c.document_id and d.generation_id=c.generation_id and d.family=v_family and d.group_key='worker_core')
         is distinct from (select coalesce(jsonb_agg(a.value order by a.value->>'key'),'[]'::jsonb) from jsonb_array_elements(ids) a)
      or (v_family in ('chunks','images') and jsonb_array_length(ids)=0) then raise exception 'managed_native_parent_closure_population_mismatch';end if;
    expected_ids:=expected_ids||ids;
    groups:=groups||jsonb_build_array(jsonb_build_object('family',v_family,'groupKey','worker_core','declaration',g));
  end loop;
  select jsonb_agg(a.value->'preparedUnitId' order by a.value->>'family' collate "C",a.value->'preparedUnitId'->>'key' collate "C") into actual_ids
    from jsonb_array_elements((p_packet->'rows')||(p_packet->'parents')) a;
  if actual_ids is distinct from (select jsonb_agg(a.value order by a.value->>'family' collate "C",a.value->>'key' collate "C") from jsonb_array_elements(expected_ids) a)
    then raise exception 'managed_native_parent_closure_population_mismatch';end if;
  foreach k in array array['rows','parents'] loop
    if (select coalesce(jsonb_agg(a.value->'preparedUnitId' order by a.ord),'[]'::jsonb) from jsonb_array_elements(p_packet->k) with ordinality a(value,ord))
      is distinct from (select coalesce(jsonb_agg(a.value->'preparedUnitId' order by a.value->>'family' collate "C",a.value->'preparedUnitId'->>'key' collate "C"),'[]'::jsonb) from jsonb_array_elements(p_packet->k) a)
      then raise exception 'managed_native_parent_closure_population_mismatch';end if;
  end loop;
  for item in select value from jsonb_array_elements(p_packet->'rows') loop
    v_family:=item->>'family';
    if not ingestion_generation_evidence.keys(item,array['family','groupKey','preparedUnitId','preparedArtifact','body']) or item->>'groupKey' is distinct from 'worker_core'
      or item->'preparedUnitId'->>'family' is distinct from v_family or v_family not in ('chunks','embedding_fields','index_units') then raise exception 'managed_native_parent_closure_invalid_packet';end if;
    prepared:=ingestion_generation_evidence.managed_vector_artifact(c,item->'preparedUnitId');u:=prepared->'declaration';
    if item->'preparedArtifact' is distinct from prepared->'artifact' or u->>'groupKey' is distinct from 'worker_core'
      or u->>'representation' is distinct from 'provenance_json' or u->>'qualification' is distinct from 'derived_unverified' or u->'sourceEvidenceIds' is distinct from '[]'::jsonb
      or prepared->'artifact'->>'locator' is distinct from 'prepared:'||v_family||':'||(item->'preparedUnitId'->>'key')
      or jsonb_typeof(u->'dependencies') is distinct from 'array'
      or u->'required' is distinct from to_jsonb(v_family='chunks') then raise exception 'managed_native_parent_closure_prepared_mismatch';end if;
    b:=convert_from(decode(prepared->'artifact'->>'bytesHex','hex'),'UTF8')::jsonb;r:=item->'body';
    keys_expected:=case v_family
      when 'chunks' then array['id','document_id','page_number','chunk_index','section_heading','section_path','heading_level','parent_heading','anchor_id','content','retrieval_synopsis','token_estimate','image_ids','content_hash','index_generation_id','metadata']
      when 'embedding_fields' then array['document_id','owner_id','source_chunk_id','field_type','content','metadata']
      else array['owner_id','document_id','unit_type','source_chunk_id','source_image_id','page_start','page_end','heading_path','title','content','normalized_terms','source_span','quality_score','extraction_mode','metadata'] end;
    if not ingestion_generation_evidence.keys(b,keys_expected) or jsonb_typeof(r) is distinct from 'object'
      or (r-array['id','embedding']) is distinct from (b-'id') or r->>'id' is distinct from item->'preparedUnitId'->>'key'
      or b->>'document_id' is distinct from c.document_id::text or jsonb_typeof(b->'metadata') is distinct from 'object'
      or b->'metadata'->>'index_generation_id' is distinct from c.generation_id::text
      or (b->'metadata') ?| array['ingestion_job_id','ingestion_job_kind','ingestion_lease_token']
      or jsonb_typeof(b->'content') is distinct from 'string' or length(btrim(b->>'content'))=0
      or (v_family<>'chunks' and b->'owner_id' is distinct from c.source_snapshot->'owner_id')
      or (v_family='chunks' and (b->>'id' is distinct from r->>'id' or b->>'index_generation_id' is distinct from c.generation_id::text))
      or jsonb_typeof(r->'embedding') is distinct from 'array' then raise exception 'managed_native_parent_closure_body_mismatch';end if;
    -- Preserve strict prepared-body types; composite casts alone also accept coerced strings.
    if v_family='chunks' then
      if jsonb_typeof(b->'chunk_index')<>'number' or coalesce(b->>'chunk_index','') !~ '^(0|[1-9][0-9]*)$'
        or jsonb_typeof(b->'token_estimate')<>'number' or coalesce(b->>'token_estimate','') !~ '^(0|[1-9][0-9]*)$'
        or jsonb_typeof(b->'content_hash')<>'string' or jsonb_typeof(b->'section_path')<>'array' or jsonb_typeof(b->'image_ids')<>'array'
        then raise exception 'managed_native_parent_closure_body_mismatch';end if;
      foreach k in array array['section_heading','parent_heading','anchor_id','retrieval_synopsis'] loop
        if b->k<>'null'::jsonb and jsonb_typeof(b->k)<>'string' then raise exception 'managed_native_parent_closure_body_mismatch';end if;
      end loop;
      if b->'page_number'<>'null'::jsonb and (jsonb_typeof(b->'page_number')<>'number' or (b->>'page_number') !~ '^[1-9][0-9]*$')
        or b->'heading_level'<>'null'::jsonb and (jsonb_typeof(b->'heading_level')<>'number' or (b->>'heading_level') !~ '^-?(0|[1-9][0-9]*)$')
        or exists(select 1 from jsonb_array_elements(b->'section_path') a where jsonb_typeof(a.value)<>'string') then raise exception 'managed_native_parent_closure_body_mismatch';end if;
    elsif v_family='embedding_fields' then
      if jsonb_typeof(b->'source_chunk_id')<>'string' or jsonb_typeof(b->'field_type')<>'string'
        or b->>'field_type' not in ('chunk_high_yield','table_row','image_caption','clinical_action','threshold_fact','section_context','document_title','document_summary')
        then raise exception 'managed_native_parent_closure_body_mismatch';end if;
    else
      if jsonb_typeof(b->'title')<>'string' or jsonb_typeof(b->'unit_type')<>'string' or jsonb_typeof(b->'quality_score')<>'number' or jsonb_typeof(b->'extraction_mode')<>'string'
        then raise exception 'managed_native_parent_closure_body_mismatch';end if;
      foreach k in array array['page_start','page_end'] loop
        if b->k<>'null'::jsonb and (jsonb_typeof(b->k)<>'number' or (b->>k) !~ '^(0|[1-9][0-9]*)$') then raise exception 'managed_native_parent_closure_body_mismatch';end if;
      end loop;
      if b->'source_span'<>'null'::jsonb then
        if not ingestion_generation_evidence.keys(b->'source_span',array['page_number','line_start','line_end','character_start','character_end','excerpt'])
          or jsonb_typeof(b->'source_span'->'excerpt')<>'string' then raise exception 'managed_native_parent_closure_body_mismatch';end if;
        foreach k in array array['page_number','line_start','line_end','character_start','character_end'] loop
          if b->'source_span'->k<>'null'::jsonb and (jsonb_typeof(b->'source_span'->k)<>'number' or (b->'source_span'->>k) !~ '^(0|[1-9][0-9]*)$') then raise exception 'managed_native_parent_closure_body_mismatch';end if;
        end loop;
      end if;
    end if;
    if jsonb_array_length(r->'embedding')<>1536 or exists(select 1 from jsonb_array_elements(r->'embedding') a where jsonb_typeof(a.value)<>'number') then raise exception 'managed_native_parent_closure_invalid_vector';end if;
    v:=((r->'embedding')::text)::extensions.vector(1536);
    text_input:=b->>'content';
    if v_family='index_units' then
      if jsonb_typeof(b->'heading_path')<>'array' or jsonb_typeof(b->'normalized_terms')<>'array'
        or exists(select 1 from jsonb_array_elements((b->'heading_path')||(b->'normalized_terms')) a where jsonb_typeof(a.value)<>'string') then raise exception 'managed_native_parent_closure_body_mismatch';end if;
      text_input:='Type: '||(b->>'unit_type')||E'\nTitle: '||(b->>'title')
        ||case when jsonb_array_length(b->'heading_path')>0 then E'\nPath: '||(select string_agg(a.value,' > ' order by a.ord) from jsonb_array_elements_text(b->'heading_path') with ordinality a(value,ord)) else '' end
        ||E'\nContent: '||(b->>'content')
        ||case when jsonb_array_length(b->'normalized_terms')>0 then E'\nTerms: '||(select string_agg(a.value,', ' order by a.ord) from jsonb_array_elements_text(b->'normalized_terms') with ordinality a(value,ord)) else '' end;
    end if;
    r:=b||jsonb_build_object('id',item->'preparedUnitId'->>'key','index_generation_id',c.generation_id,'embedding',v::text,
      'metadata',b->'metadata'||jsonb_build_object('ingestion_job_id',c.job_id,'ingestion_job_kind','node','ingestion_lease_token',c.first_lease_token));
    if v_family='chunks' then
      cr:=jsonb_populate_record(null::public.document_chunks,r);
      r:=(to_jsonb(cr)-array['created_at','search_tsv','embedding'])||jsonb_build_object('embedding',(cr.embedding::text)::jsonb);
      if exists(select 1 from public.document_chunks a where (a.id=cr.id or (a.document_id=c.document_id and a.index_generation_id=c.generation_id and a.chunk_index=cr.chunk_index))
        and not (j.status='completed' and c.source_sha256='sha256:abbc8107a09582e18f36bf4905c75f1fc78af70cd516851b89bff8919ca5bece' and a.id=cr.id and
          (to_jsonb(a)-array['created_at','search_tsv','embedding'])||jsonb_build_object('embedding',(a.embedding::text)::jsonb)=r))
