        or table_md->'table_title' is distinct from 'null'::jsonb or table_md->'table_label' is distinct from 'null'::jsonb
        or (table_md->'table_role' is distinct from 'null'::jsonb and table_md->'table_role' is distinct from '"unclear"'::jsonb)
        or jsonb_typeof(table_md->'table_text') is distinct from 'string' or length(table_md->>'table_text')>24000
        or jsonb_typeof(table_md->'accessible_table_markdown') is distinct from 'string' or length(table_md->>'accessible_table_markdown')>24000
        then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
      if jsonb_array_length(table_md->'table_rows') not between 2 and 400 or table_md->'row_count' is distinct from to_jsonb(jsonb_array_length(table_md->'table_rows'))
        or table_md->'column_count' is distinct from '5'::jsonb or table_md->'table_rows'->0 is distinct from table_md->'table_columns'
        or jsonb_array_length(facts)<>jsonb_array_length(table_md->'table_rows')-1 then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
      total_table_rows:=total_table_rows+jsonb_array_length(table_md->'table_rows');
      for rec in select value from jsonb_array_elements(table_md->'table_rows') loop
        if jsonb_typeof(rec)<>'array' then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
        if jsonb_array_length(rec)<>5 or exists(select 1 from jsonb_array_elements(rec) a where jsonb_typeof(a.value)<>'string' or length(a.value#>>'{}')>240) then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
      end loop;
      for ord in 1..jsonb_array_length(facts) loop
        rec:=facts->(ord-1);
        if rec->'metadata'->'row_index' is distinct from to_jsonb(ord) or rec->'metadata'->'columns' is distinct from table_md->'table_columns'
          or rec->'metadata'->'cells' is distinct from table_md->'table_rows'->ord or rec->'row_label' is distinct from table_md->'table_rows'->ord->0
          or rec->'clinical_parameter' is distinct from table_md->'table_rows'->ord->0 or rec->'page_number' is distinct from b->'page_number'
          or rec->'table_title' is distinct from table_md->'table_title' then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
      end loop;
    elsif jsonb_array_length(facts)<>0 then raise exception 'managed_native_parent_closure_native_table_mismatch';end if;
  end loop;
  if total_table_rows>400 then raise exception 'managed_native_parent_closure_transport_limit';end if;
  -- Reconstruct body links and native semantic matches before accepting any final parent edge.
  for item in select value from jsonb_array_elements(normalized) loop
    v_family:=item->>'family';b:=item->'body';u:=item->'declaration';links:='[]'::jsonb;
    for rec in select value from jsonb_array_elements(jsonb_build_array(b,b->'metadata')) loop
      foreach k in array array['source_chunk_id','source_image_id'] loop
        if rec ? k and rec->k<>'null'::jsonb then
          if jsonb_typeof(rec->k)<>'string' then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
          links:=links||jsonb_build_array(jsonb_build_object('family',case when k='source_chunk_id' then 'chunks' else 'images' end,'key',rec->>k));
        end if;
      end loop;
      foreach k in array array['source_chunk_ids','chunk_ids','source_image_ids','image_ids'] loop
        if rec ? k then
          if jsonb_typeof(rec->k)<>'array' then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
          for x in select value from jsonb_array_elements(rec->k) loop
            if jsonb_typeof(x)<>'string' then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
            links:=links||jsonb_build_array(jsonb_build_object('family',case when k in ('source_chunk_ids','chunk_ids') then 'chunks' else 'images' end,'key',x#>>'{}'));
          end loop;
        end if;
      end loop;
      if rec ? 'section_id' and rec->'section_id'<>'null'::jsonb then raise exception 'managed_native_parent_closure_parent_not_staged';end if;
    end loop;
    if b->'metadata'->>'source' in ('document_sections','document_memory_cards') then raise exception 'managed_native_parent_closure_parent_not_staged';end if;
    if v_family='table_facts' then
      select a.value->'body' into image_row from jsonb_array_elements(normalized) a where a.value->>'family'='images' and a.value->>'rowId'=b->>'source_image_id';
      select a.value->'body' into chunk_row from jsonb_array_elements(normalized) a where a.value->>'family'='chunks' and a.value->>'rowId'=b->>'source_chunk_id';
      if image_row is null or chunk_row is null or image_row->>'source_kind'<>'table_crop'
        or image_row->'page_number' is distinct from b->'page_number' or chunk_row->'page_number' is distinct from b->'page_number'
        or not chunk_row->'image_ids' @> jsonb_build_array(b->'source_image_id') then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
    end if;
    if v_family='embedding_fields' and b->'metadata'->>'source'='document_table_facts' then
      select coalesce(jsonb_agg(a.value->'prepared'->'unitId' order by a.value->>'rowId' collate "C"),'[]'::jsonb) into matched from jsonb_array_elements(normalized) a
        where a.value->>'family'='table_facts' and a.value->'body'->'source_chunk_id'=b->'source_chunk_id'
          and a.value->'body'->'source_image_id'=b->'metadata'->'source_image_id' and a.value->'body'->'table_title'=b->'metadata'->'table_title'
          and a.value->'body'->'page_number'=b->'metadata'->'page_number';
      if jsonb_array_length(matched)=0 then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
      links:=links||matched;
    end if;
    if v_family='index_units' and b->>'unit_type'='table_fact' then
      select coalesce(jsonb_agg(a.value->'prepared'->'unitId'),'[]'::jsonb) into matched from jsonb_array_elements(normalized) a
        where a.value->>'family'='table_facts' and a.value->'body'->'source_chunk_id'=b->'source_chunk_id' and a.value->'body'->'source_image_id'=b->'source_image_id'
          and a.value->'body'->'metadata'->'row_index'=b->'metadata'->'row_index' and a.value->'body'->'metadata'->'columns'=b->'metadata'->'columns'
          and a.value->'body'->'metadata'->'cells'=b->'metadata'->'cells' and a.value->'body'->'metadata'=b->'metadata'->'table_fact_metadata'
          and b->'metadata'->'named_cells'=(select jsonb_agg(jsonb_build_object('column',t.value,'cell',a.value->'body'->'metadata'->'cells'->(t.ord::integer-1)) order by t.ord)
            from jsonb_array_elements(a.value->'body'->'metadata'->'columns') with ordinality t(value,ord));
      if jsonb_array_length(matched)<>1 then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
      links:=links||matched;
    end if;
    select coalesce(jsonb_agg(x.value order by x.value->>'family' collate "C",x.value->>'key' collate "C"),'[]'::jsonb) into semantic from (select distinct a.value from jsonb_array_elements(links) a) x;
    select coalesce(jsonb_agg(a.value order by a.value->>'family' collate "C",a.value->>'key' collate "C"),'[]'::jsonb) into declared_semantic from jsonb_array_elements(u->'dependencies') a where a.value->>'family' in ('images','chunks','table_facts');
    -- Prepared declarations may additionally pin qualifier chunks without rewriting the raw body.
    -- Body/native links must all be declared; extra semantic edges can only be authentic chunk dependencies.
    -- The loop below authenticates every dependency; the full graph/order and receipt pins retain them all.
    if not declared_semantic @> semantic
      or exists(select 1 from jsonb_array_elements(declared_semantic) a where not semantic @> jsonb_build_array(a.value) and a.value->>'family'<>'chunks')
      or jsonb_array_length(u->'dependencies')<>(select count(distinct a.value) from jsonb_array_elements(u->'dependencies') a)
      then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
    for dep in select value from jsonb_array_elements(u->'dependencies') loop
      pa:=ingestion_generation_evidence.managed_vector_artifact(c,dep);
      if pa->'declaration'->>'groupKey'='deep_memory' or dep->>'family' not in ('images','chunks','table_facts','pages','private_objects','attempt_control')
        then raise exception 'managed_native_parent_closure_parent_not_staged';end if;
      if dep->>'family' in ('images','chunks','table_facts') then
        if not expected_ids @> jsonb_build_array(dep) or pa->'declaration'->>'groupKey'<>'worker_core'
          or v_family='images' or (v_family in ('chunks','table_facts') and dep->>'family'='table_facts') then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
        if dep->>'family'='images' and exists(select 1 from jsonb_array_elements(normalized) a where a.value->'prepared'->'unitId'=dep and a.value->'body'->>'source_kind'='cover_page') then raise exception 'managed_native_parent_closure_parent_mismatch';end if;
      elsif dep->>'family'='private_objects' and dep->>'key' like 'image:%' and v_family<>'images' then
        raise exception 'managed_native_parent_closure_parent_not_staged';
      end if;
    end loop;
  end loop;
  -- A bounded topological order closes images -> chunks -> facts -> vector derivatives; no recursive hash graph.
  select jsonb_agg(a.value->'prepared'->'unitId') into pending from jsonb_array_elements(normalized) a;
  while jsonb_array_length(pending)>0 loop
    select a.value->'prepared'->'unitId' into next_id from jsonb_array_elements(normalized) a
      where pending @> jsonb_build_array(a.value->'prepared'->'unitId') and not exists(select 1 from jsonb_array_elements(a.value->'dependencies') d
        where d.value->>'family' in ('images','chunks','table_facts') and not done @> jsonb_build_array(d.value))
      order by case a.value->>'family' when 'images' then 0 when 'chunks' then 1 when 'table_facts' then 2 else 3 end,a.value->>'family' collate "C",a.value->>'rowId' collate "C" limit 1;
    if next_id is null then raise exception 'managed_native_parent_closure_parent_cycle';end if;
    done:=done||jsonb_build_array(next_id);
    select coalesce(jsonb_agg(a.value),'[]'::jsonb) into pending from jsonb_array_elements(pending) a where a.value<>next_id;
  end loop;
  -- Refuse another protocol/candidate's identifiers, including registered-but-not-yet-written projections.
  if exists(select 1 from ingestion_generation_evidence.managed_vector_packets p where p.document_id=c.document_id and p.generation_id=c.generation_id and p.request->>'version' is distinct from 'managed-native-parent-closure-v1')
    or exists(select 1 from ingestion_generation_evidence.scoped_projection_expectations e where e.document_id=c.document_id and e.generation_id=c.generation_id and e.projection_id=c.generation_id and e.manifest->>'version' is distinct from 'managed-native-parent-closure-manifest-v1')
    or exists(select 1 from ingestion_generation_evidence.scoped_projection_expectations e cross join lateral jsonb_array_elements(coalesce(e.manifest->'expectedRows','[]'::jsonb)) x
      join lateral jsonb_array_elements(normalized) n on x.value->>'family'=n.value->>'family' and x.value->'row'->>'id'=n.value->>'rowId')
    then raise exception 'managed_native_parent_closure_protocol_collision';end if;
  for item in select value from jsonb_array_elements(normalized) loop
    if item->>'family'='chunks' and exists(select 1 from ingestion_generation_evidence.managed_vector_chunk_rows a where
      (a.id=(item->>'rowId')::uuid or (a.document_id=c.document_id and a.index_generation_id=c.generation_id and a.chunk_index=(item->'row'->>'chunk_index')::integer))
      and (a.document_id<>c.document_id or a.index_generation_id<>c.generation_id or a.id<>(item->>'rowId')::uuid))
      or item->>'family'='embedding_fields' and exists(select 1 from ingestion_generation_evidence.managed_vector_field_rows a where a.id=(item->>'rowId')::uuid and (a.document_id<>c.document_id or a.index_generation_id<>c.generation_id))
      or item->>'family'='index_units' and exists(select 1 from ingestion_generation_evidence.managed_vector_index_rows a where a.id=(item->>'rowId')::uuid and (a.document_id<>c.document_id or a.index_generation_id<>c.generation_id))
      then raise exception 'managed_native_parent_closure_protocol_collision';end if;
    parents:='[]'::jsonb;
    for dep in select value from jsonb_array_elements(item->'dependencies') loop
      pa:=ingestion_generation_evidence.managed_vector_artifact(c,dep);
      if dep->>'family' in ('images','chunks','table_facts') then
        select a.value into strict parent from jsonb_array_elements(normalized) a where a.value->'prepared'->'unitId'=dep;
        parents:=parents||jsonb_build_array(jsonb_build_object('kind','row','unitId',dep,'preparedSha256',pa->'artifact'->'sha256','preparedByteLength',pa->'artifact'->'byteLength',
          'finalIdentity',jsonb_build_object('version','managed-native-parent-closure-row-v1','family',dep->>'family','rowId',dep->>'key'),
          'normalizedRowSha256','sha256:'||encode(extensions.digest(convert_to((parent->'row')::text,'UTF8'),'sha256'),'hex')));
      else
        parents:=parents||jsonb_build_array(jsonb_build_object('kind','retained','unitId',dep,'sha256',pa->'artifact'->'sha256','byteLength',pa->'artifact'->'byteLength','representation',pa->'artifact'->'representation'));
      end if;
    end loop;
    finished:=finished||jsonb_build_array((item-'dependencies')||jsonb_build_object('parents',parents));
  end loop;
  select jsonb_agg(jsonb_build_object('declaration',a.value->'declaration','prepared',a.value->'prepared') order by a.value->>'family' collate "C",a.value->>'rowId' collate "C") into units from jsonb_array_elements(normalized) a;
  manifest:=jsonb_build_object('version','managed-native-parent-closure-manifest-v1','qualification','derived_unverified','scope','complete_known_local_worker_core_output',
    'identity',identity,'planDigest',p_packet->>'planDigest','projectionId',c.generation_id,'sourceExpectation',c.source_expectation,'groups',groups,'units',units);
  manifest_bytes:=convert_to(manifest::text,'UTF8');
  if octet_length(manifest_bytes) not between 1 and 2097152 then raise exception 'managed_native_parent_closure_transport_limit';end if;
  return jsonb_build_object('identity',identity,'planDigest',p_packet->>'planDigest','projectionId',c.generation_id,'manifest',manifest,'order',done,'rows',finished);
end $$;

alter function ingestion_generation_evidence.validate_native_parent_closure(ingestion_generation_evidence.candidates,jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.validate_native_parent_closure(ingestion_generation_evidence.candidates,jsonb) from public,anon,authenticated,service_role;

create function ingestion_generation_evidence.native_parent_closure_bundle(p_validated jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare item jsonb;body jsonb;b bytea;h text;rows jsonb:='[]'::jsonb;population jsonb:='[]'::jsonb;pb bytea;mb bytea;mh text;counts jsonb;result jsonb;
begin
  mb:=convert_to((p_validated->'manifest')::text,'UTF8');mh:='sha256:'||encode(extensions.digest(mb,'sha256'),'hex');
  for item in select value from jsonb_array_elements(p_validated->'rows') order by value->>'family' collate "C",value->>'rowId' collate "C" loop
    body:=jsonb_build_object('version','managed-native-parent-closure-row-v1','qualification','derived_unverified','identity',p_validated->'identity','planDigest',p_validated->>'planDigest',
      'projectionId',p_validated->'projectionId','family',item->>'family','groupKey','worker_core','rowId',item->>'rowId','rowKind',item->>'rowKind','prepared',item->'prepared',
      'parents',item->'parents','retainedReferences',item->'retainedReferences','vectorInput',item->'vectorInput','row',item->'row');
    b:=convert_to(body::text,'UTF8');h:='sha256:'||encode(extensions.digest(b,'sha256'),'hex');
    if item->>'family' in ('images','table_facts') and octet_length(b) not between 1 and 2097152 then raise exception 'managed_native_parent_closure_transport_limit';end if;
    rows:=rows||jsonb_build_array(jsonb_build_object('family',item->>'family','rowId',item->>'rowId','rowKind',item->>'rowKind','prepared',item->'prepared','row',item->'row',
      'receipt',jsonb_build_object('bytesHex',encode(b,'hex'),'sha256',h,'byteLength',octet_length(b))));
    population:=population||jsonb_build_array(jsonb_build_object('family',item->>'family','rowId',item->>'rowId','rowKind',item->>'rowKind','preparedSha256',item->'prepared'->>'sha256',
      'preparedByteLength',item->'prepared'->'byteLength','normalizedRowSha256','sha256:'||encode(extensions.digest(convert_to((item->'row')::text,'UTF8'),'sha256'),'hex'),'receiptSha256',h));
  end loop;
  pb:=convert_to(jsonb_build_object('version','managed-native-parent-closure-population-v1','identity',p_validated->'identity','planDigest',p_validated->>'planDigest',
    'projectionId',p_validated->'projectionId','manifestSha256',mh,'population',population)::text,'UTF8');
  select jsonb_build_object('chunks',count(*) filter(where a.value->>'family'='chunks'),'embedding_fields',count(*) filter(where a.value->>'family'='embedding_fields'),
    'images',count(*) filter(where a.value->>'family'='images'),'index_units',count(*) filter(where a.value->>'family'='index_units'),'table_facts',count(*) filter(where a.value->>'family'='table_facts')) into counts from jsonb_array_elements(rows) a;
  result:=jsonb_build_object('ok',true,'managedNativeParentClosure',jsonb_build_object('version','managed-native-parent-closure-readback-v1','status','retained_unverified',
    'activated',false,'terminalEligibility','unavailable','providerExecution','unverified','imageProcessing','capture_capsules_only','sourceAssessment','unverified',
    'identity',p_validated->'identity','planDigest',p_validated->>'planDigest','projectionId',p_validated->'projectionId',
    'manifest',jsonb_build_object('bytesHex',encode(mb,'hex'),'sha256',mh,'byteLength',octet_length(mb)),
    'sqlPopulationDigest','sha256:'||encode(extensions.digest(pb,'sha256'),'hex'),
    'populationCommitment',jsonb_build_object('bytesHex',encode(pb,'hex'),'sha256','sha256:'||encode(extensions.digest(pb,'sha256'),'hex'),'byteLength',octet_length(pb)),'counts',counts,'rows',rows));
  if octet_length(convert_to(result::text,'UTF8'))>16777216 then raise exception 'managed_native_parent_closure_transport_limit';end if;
  return result;
end $$;

alter function ingestion_generation_evidence.native_parent_closure_bundle(jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.native_parent_closure_bundle(jsonb) from public,anon,authenticated,service_role;

create function ingestion_generation_evidence.checked_native_parent_closure(c ingestion_generation_evidence.candidates,p_expected_plan_digest text)
returns jsonb language plpgsql set search_path='' as $$
declare p ingestion_generation_evidence.managed_vector_packets;validated jsonb;result jsonb;item jsonb;stored jsonb;controls jsonb;sha text;
  receipt ingestion_generation_evidence.managed_vector_final_receipts;cr public.document_chunks;fr public.document_embedding_fields;ir public.document_index_units;actual_count bigint;parent_count bigint;ex ingestion_generation_evidence.scoped_projection_expectations;art ingestion_generation_evidence.scoped_projection_artifacts;raw_prepared jsonb;
begin
  if c is null or coalesce(p_expected_plan_digest,'') !~ '^sha256:[0-9a-f]{64}$' then raise exception 'managed_native_parent_closure_invalid_packet';end if;
  select * into p from ingestion_generation_evidence.managed_vector_packets where document_id=c.document_id and generation_id=c.generation_id;
  if not found then
    if exists(select 1 from ingestion_generation_evidence.scoped_projection_expectations e where e.document_id=c.document_id and e.generation_id=c.generation_id and e.projection_id=c.generation_id)
      or exists(select 1 from ingestion_generation_evidence.scoped_projection_rows a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id)
      or exists(select 1 from ingestion_generation_evidence.scoped_projection_artifacts a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id)
      then raise exception 'managed_native_parent_closure_protocol_collision';end if;
    return jsonb_build_object('ok',true,'managedNativeParentClosure',jsonb_build_object('version','managed-native-parent-closure-readback-v1','status','pending','reason','packet_not_staged',
      'activated',false,'terminalEligibility','unavailable','providerExecution','unverified','imageProcessing','capture_capsules_only','sourceAssessment','unverified'));
  end if;
  if p.request->>'version' is distinct from 'managed-native-parent-closure-v1' then raise exception 'managed_native_parent_closure_protocol_collision';end if;
  if p.plan_digest is distinct from p_expected_plan_digest then raise exception 'managed_native_parent_closure_replay_mismatch';end if;
  validated:=ingestion_generation_evidence.validate_native_parent_closure(c,p.request);
  result:=ingestion_generation_evidence.native_parent_closure_bundle(validated);
  if p.identity is distinct from validated->'identity' or p.plan_digest is distinct from validated->>'planDigest'
    or p.population_bytes is distinct from decode(result->'managedNativeParentClosure'->'populationCommitment'->>'bytesHex','hex')
    or p.population_sha256 is distinct from result->'managedNativeParentClosure'->>'sqlPopulationDigest' then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  select * into ex from ingestion_generation_evidence.scoped_projection_expectations e where e.document_id=c.document_id and e.generation_id=c.generation_id and e.projection_id=c.generation_id;
  if not found or ex.manifest is distinct from validated->'manifest'
    or ex.manifest_bytes is distinct from decode(result->'managedNativeParentClosure'->'manifest'->>'bytesHex','hex')
    or ex.sha256 is distinct from result->'managedNativeParentClosure'->'manifest'->>'sha256'
    or ex.byte_length is distinct from (result->'managedNativeParentClosure'->'manifest'->>'byteLength')::bigint then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  for item in select value from jsonb_array_elements(result->'managedNativeParentClosure'->'rows') loop
    if item->>'family' in ('images','table_facts') then
      select a.row_data into stored from ingestion_generation_evidence.scoped_projection_rows a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id and a.family=item->>'family' and a.row_id=(item->>'rowId')::uuid;
      if not found or stored is distinct from item->'row' then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
      select a.value->'rawPrepared' into strict raw_prepared from jsonb_array_elements(validated->'rows') a where a.value->>'family'=item->>'family' and a.value->>'rowId'=item->>'rowId';
      select * into art from ingestion_generation_evidence.scoped_projection_artifacts a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id and a.family=item->>'family' and a.row_id=(item->>'rowId')::uuid and a.phase='prepared';
      if not found or art.artifact_bytes is distinct from decode(raw_prepared->>'bytesHex','hex') or art.sha256 is distinct from raw_prepared->>'sha256' or art.byte_length is distinct from (raw_prepared->>'byteLength')::bigint then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
      select * into art from ingestion_generation_evidence.scoped_projection_artifacts a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id and a.family=item->>'family' and a.row_id=(item->>'rowId')::uuid and a.phase='final';
      if not found or art.artifact_bytes is distinct from decode(item->'receipt'->>'bytesHex','hex') or art.sha256 is distinct from item->'receipt'->>'sha256' or art.byte_length is distinct from (item->'receipt'->>'byteLength')::bigint then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
      continue;
    end if;
    if item->>'family'='chunks' then
      select to_jsonb(a),a.packet_identity,a.prepared_sha256 into stored,controls,sha from ingestion_generation_evidence.managed_vector_chunk_rows a where a.id=(item->>'rowId')::uuid and a.document_id=c.document_id and a.index_generation_id=c.generation_id;
      cr:=jsonb_populate_record(null::public.document_chunks,stored);stored:=(to_jsonb(cr)-array['created_at','search_tsv','embedding'])||jsonb_build_object('embedding',(cr.embedding::text)::jsonb);
    elsif item->>'family'='embedding_fields' then
      select to_jsonb(a),a.packet_identity,a.prepared_sha256 into stored,controls,sha from ingestion_generation_evidence.managed_vector_field_rows a where a.id=(item->>'rowId')::uuid and a.document_id=c.document_id and a.index_generation_id=c.generation_id;
      fr:=jsonb_populate_record(null::public.document_embedding_fields,stored);stored:=(to_jsonb(fr)-array['created_at','search_tsv','embedding'])||jsonb_build_object('embedding',(fr.embedding::text)::jsonb);
    else
      select to_jsonb(a),a.packet_identity,a.prepared_sha256 into stored,controls,sha from ingestion_generation_evidence.managed_vector_index_rows a where a.id=(item->>'rowId')::uuid and a.document_id=c.document_id and a.index_generation_id=c.generation_id;
      ir:=jsonb_populate_record(null::public.document_index_units,stored);stored:=(to_jsonb(ir)-array['created_at','updated_at','search_tsv','embedding'])||jsonb_build_object('embedding',(ir.embedding::text)::jsonb);
    end if;
    if controls is distinct from p.identity or sha is distinct from item->'prepared'->>'sha256' or stored is distinct from item->'row' then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
    select * into receipt from ingestion_generation_evidence.managed_vector_final_receipts where document_id=c.document_id and generation_id=c.generation_id and family=item->>'family' and row_id=(item->>'rowId')::uuid;
    if not found or receipt.artifact_bytes is distinct from decode(item->'receipt'->>'bytesHex','hex') or receipt.sha256 is distinct from item->'receipt'->>'sha256'
      or receipt.byte_length is distinct from (item->'receipt'->>'byteLength')::bigint then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  end loop;
  select (select count(*) from ingestion_generation_evidence.managed_vector_chunk_rows where document_id=c.document_id and index_generation_id=c.generation_id)
    +(select count(*) from ingestion_generation_evidence.managed_vector_field_rows where document_id=c.document_id and index_generation_id=c.generation_id)
    +(select count(*) from ingestion_generation_evidence.managed_vector_index_rows where document_id=c.document_id and index_generation_id=c.generation_id) into actual_count;
  select count(*) into parent_count from ingestion_generation_evidence.scoped_projection_rows a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id;
  if (select count(*) from ingestion_generation_evidence.scoped_projection_artifacts a where a.document_id=c.document_id and a.generation_id=c.generation_id and a.projection_id=c.generation_id)<>2*parent_count then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  if actual_count+parent_count<>jsonb_array_length(validated->'rows') or (select count(*) from ingestion_generation_evidence.managed_vector_final_receipts where document_id=c.document_id and generation_id=c.generation_id)<>actual_count then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  return result;
end $$;

alter function ingestion_generation_evidence.checked_native_parent_closure(ingestion_generation_evidence.candidates,text) owner to postgres;
revoke all on function ingestion_generation_evidence.checked_native_parent_closure(ingestion_generation_evidence.candidates,text) from public,anon,authenticated,service_role;

create function ingestion_generation_evidence.read_native_parent_closure(p_fence jsonb,p_generation uuid,p_expected_plan_digest text)
returns jsonb language plpgsql set search_path='' as $$
declare c ingestion_generation_evidence.candidates; result jsonb;
begin
 if p_generation is null or not ingestion_generation_evidence.visual_unit_fence(p_fence) or coalesce(p_expected_plan_digest,'') !~ '^sha256:[0-9a-f]{64}$'
  then raise exception 'managed_native_parent_closure_invalid_packet';end if;
 c:=ingestion_generation_evidence.lock_candidate(p_fence,p_generation);
 if c is null then return jsonb_build_object('ok',false,'reason','lease_lost');end if;
 result:=ingestion_generation_evidence.checked_native_parent_closure(c,p_expected_plan_digest);
 if ingestion_generation_evidence.lock_candidate(p_fence,p_generation) is null then return jsonb_build_object('ok',false,'reason','lease_lost');end if;
 return result;
end $$;

alter function ingestion_generation_evidence.read_native_parent_closure(jsonb,uuid,text) owner to postgres;
revoke all on function ingestion_generation_evidence.read_native_parent_closure(jsonb,uuid,text) from public,anon,authenticated,service_role;

create function ingestion_generation_evidence.stage_native_parent_closure(p_fence jsonb,p_generation uuid,p_packet jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare c ingestion_generation_evidence.candidates;p ingestion_generation_evidence.managed_vector_packets;validated jsonb;result jsonb;item jsonb;r jsonb;raw_prepared jsonb;prior_read jsonb;
begin
  if p_generation is null or not ingestion_generation_evidence.visual_unit_fence(p_fence) then raise exception 'managed_native_parent_closure_invalid_packet';end if;
  c:=ingestion_generation_evidence.lock_candidate(p_fence,p_generation);
  if c is null then return jsonb_build_object('ok',false,'reason','lease_lost');end if;
  validated:=ingestion_generation_evidence.validate_native_parent_closure(c,p_packet);
  result:=ingestion_generation_evidence.native_parent_closure_bundle(validated);
  select * into p from ingestion_generation_evidence.managed_vector_packets where document_id=c.document_id and generation_id=c.generation_id;
  if found then
    if p.request is distinct from p_packet or p.identity is distinct from validated->'identity' or p.plan_digest is distinct from p_packet->>'planDigest'
      or p.population_bytes is distinct from decode(result->'managedNativeParentClosure'->'populationCommitment'->>'bytesHex','hex') then raise exception 'managed_native_parent_closure_replay_mismatch';end if;
    return ingestion_generation_evidence.read_native_parent_closure(p_fence,p_generation,p_packet->>'planDigest');
  end if;
  -- The current read path refuses any orphan/foreign projection instead of adopting it.
  prior_read:=ingestion_generation_evidence.read_native_parent_closure(p_fence,p_generation,p_packet->>'planDigest');
  if prior_read->'ok' is distinct from 'true'::jsonb then raise exception 'managed_native_parent_closure_lease_lost';end if;
  if prior_read->'managedNativeParentClosure'->>'status' is distinct from 'pending' then raise exception 'managed_native_parent_closure_stored_mismatch';end if;
  insert into ingestion_generation_evidence.managed_vector_packets values(c.document_id,c.generation_id,validated->'identity',p_packet->>'planDigest',p_packet,
    decode(result->'managedNativeParentClosure'->'populationCommitment'->>'bytesHex','hex'),result->'managedNativeParentClosure'->>'sqlPopulationDigest');
  insert into ingestion_generation_evidence.scoped_projection_expectations values(c.document_id,c.generation_id,c.generation_id,validated->'manifest',
    decode(result->'managedNativeParentClosure'->'manifest'->>'bytesHex','hex'),result->'managedNativeParentClosure'->'manifest'->>'sha256',(result->'managedNativeParentClosure'->'manifest'->>'byteLength')::bigint);
  for item in select a.value from jsonb_array_elements(validated->'order') with ordinality o(value,ord)
    join lateral jsonb_array_elements(result->'managedNativeParentClosure'->'rows') a on a.value->'prepared'->'unitId'=o.value order by o.ord loop
    if item->>'family' in ('images','table_facts') then
      select a.value->'rawPrepared' into strict raw_prepared from jsonb_array_elements(validated->'rows') a where a.value->>'family'=item->>'family' and a.value->>'rowId'=item->>'rowId';
      insert into ingestion_generation_evidence.scoped_projection_rows values(c.document_id,c.generation_id,c.generation_id,item->>'family',(item->>'rowId')::uuid,item->'row');
      insert into ingestion_generation_evidence.scoped_projection_artifacts values(c.document_id,c.generation_id,c.generation_id,item->>'family',(item->>'rowId')::uuid,'prepared',
        decode(raw_prepared->>'bytesHex','hex'),raw_prepared->>'sha256',(raw_prepared->>'byteLength')::bigint);
      insert into ingestion_generation_evidence.scoped_projection_artifacts values(c.document_id,c.generation_id,c.generation_id,item->>'family',(item->>'rowId')::uuid,'final',
        decode(item->'receipt'->>'bytesHex','hex'),item->'receipt'->>'sha256',(item->'receipt'->>'byteLength')::bigint);
      continue;
    end if;

    r:=item->'row';r:=r||jsonb_build_object('embedding',(r->'embedding')::text);
    if item->>'family'='chunks' then
      insert into ingestion_generation_evidence.managed_vector_chunk_rows(id,document_id,page_number,chunk_index,section_heading,section_path,heading_level,parent_heading,anchor_id,content,retrieval_synopsis,content_hash,index_generation_id,token_estimate,image_ids,metadata,embedding,packet_identity,prepared_sha256)
      select a.id,a.document_id,a.page_number,a.chunk_index,a.section_heading,a.section_path,a.heading_level,a.parent_heading,a.anchor_id,a.content,a.retrieval_synopsis,a.content_hash,a.index_generation_id,a.token_estimate,a.image_ids,a.metadata,a.embedding,validated->'identity',item->'prepared'->>'sha256' from jsonb_populate_record(null::public.document_chunks,r) a;
    elsif item->>'family'='embedding_fields' then
      insert into ingestion_generation_evidence.managed_vector_field_rows(id,owner_id,document_id,source_chunk_id,field_type,content,content_hash,embedding,index_generation_id,metadata,packet_identity,prepared_sha256)
      select a.id,a.owner_id,a.document_id,a.source_chunk_id,a.field_type,a.content,a.content_hash,a.embedding,a.index_generation_id,a.metadata,validated->'identity',item->'prepared'->>'sha256' from jsonb_populate_record(null::public.document_embedding_fields,r) a;
    else
      insert into ingestion_generation_evidence.managed_vector_index_rows(id,owner_id,document_id,unit_type,source_chunk_id,source_image_id,page_start,page_end,heading_path,title,content,normalized_terms,source_span,quality_score,extraction_mode,index_generation_id,producer,artifact_generation_id,embedding,metadata,packet_identity,prepared_sha256)
      select a.id,a.owner_id,a.document_id,a.unit_type,a.source_chunk_id,a.source_image_id,a.page_start,a.page_end,a.heading_path,a.title,a.content,a.normalized_terms,a.source_span,a.quality_score,a.extraction_mode,a.index_generation_id,a.producer,a.artifact_generation_id,a.embedding,a.metadata,validated->'identity',item->'prepared'->>'sha256' from jsonb_populate_record(null::public.document_index_units,r) a;
    end if;
    insert into ingestion_generation_evidence.managed_vector_final_receipts values(c.document_id,c.generation_id,item->>'family',(item->>'rowId')::uuid,
      decode(item->'receipt'->>'bytesHex','hex'),item->'receipt'->>'sha256',(item->'receipt'->>'byteLength')::bigint);
  end loop;
  result:=ingestion_generation_evidence.read_native_parent_closure(p_fence,p_generation,p_packet->>'planDigest');
  -- If the lease expires during normalization/inserts, roll back every new private effect.
  if result->'ok' is distinct from 'true'::jsonb then raise exception 'managed_native_parent_closure_lease_lost';end if;
  return result;
end $$;

alter function ingestion_generation_evidence.stage_native_parent_closure(jsonb,uuid,jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.stage_native_parent_closure(jsonb,uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function public.write_ingestion_base_artifacts(p_fence jsonb, p_generation uuid, p_chunks jsonb, p_images jsonb, p_table_facts jsonb, p_embedding_fields jsonb, p_index_units jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_locked jsonb; v_document_id uuid; v_row jsonb;
begin

  if jsonb_typeof(p_chunks)='object' and p_chunks->>'version'='managed-native-parent-closure-v1' then
    if p_images is distinct from '[]'::jsonb or p_table_facts is distinct from '[]'::jsonb or p_embedding_fields is distinct from '[]'::jsonb or p_index_units is distinct from '[]'::jsonb
      then raise exception 'managed_native_parent_closure_invalid_packet';end if;
    return ingestion_generation_evidence.stage_native_parent_closure(p_fence,p_generation,p_chunks);
  end if;
    if p_generation is null or p_fence->>'job_kind' is distinct from 'node' then raise exception 'ingestion_attempt_required'; end if;
  v_locked := public.assert_current_ingestion_attempt(p_fence, p_generation);
  if v_locked is null then return jsonb_build_object('ok', false, 'reason', 'lease_lost'); end if;
  if exists(select 1 from ingestion_generation_evidence.candidates where document_id=(p_fence->>'document_id')::uuid and job_id=(p_fence->>'job_id')::uuid) then
    if jsonb_typeof(p_images) is distinct from 'array' or p_images<>'[]'::jsonb
      or jsonb_typeof(p_table_facts) is distinct from 'array' or p_table_facts<>'[]'::jsonb
      or jsonb_typeof(p_embedding_fields) is distinct from 'array' or p_embedding_fields<>'[]'::jsonb
      or jsonb_typeof(p_index_units) is distinct from 'array' or p_index_units<>'[]'::jsonb
      then return jsonb_build_object('ok',false,'reason','technical_supplier_not_implemented'); end if;
    return ingestion_generation_evidence.persist_candidate_chunks(p_fence,p_generation,p_chunks);
  end if;
  v_document_id := (p_fence->>'document_id')::uuid;
  if jsonb_typeof(p_chunks) is distinct from 'array' or jsonb_array_length(p_chunks) > 500 then raise exception 'invalid_ingestion_artifact_batch'; end if;
  for v_row in select value from jsonb_array_elements(p_chunks) loop
    if v_row->>'document_id' is distinct from v_document_id::text then raise exception 'ingestion_artifact_document_mismatch'; end if;
    perform public.assert_ingestion_artifact_sources(v_row,v_document_id,p_generation,null);

    v_row := jsonb_build_object('id',gen_random_uuid(),'metadata','{}'::jsonb,'section_path','[]'::jsonb,'heading_path','[]'::jsonb,'image_ids','[]'::jsonb,'source_chunk_ids','[]'::jsonb,'source_image_ids','[]'::jsonb,'chunk_ids','[]'::jsonb,'tags','[]'::jsonb,'normalized_terms','[]'::jsonb,'token_estimate',0,'caption','','mime_type','image/png','image_type','unclear','searchable',true,'clinical_relevance_score',0,'source_kind','embedded','summary','','extraction_quality','unknown','confidence',0.5,'quality_score',0.7,'extraction_mode','deterministic') || v_row || jsonb_build_object('index_generation_id',p_generation,
      'metadata', coalesce(v_row->'metadata','{}'::jsonb) || jsonb_build_object('index_generation_id',p_generation,'ingestion_lease_token',p_fence->>'lease_token','ingestion_job_kind',p_fence->>'job_kind','ingestion_job_id',p_fence->>'job_id'));
    v_row := v_row || jsonb_build_object('embedding',(v_row->'embedding')::text);
    insert into public.document_chunks(id,document_id,page_number,chunk_index,section_heading,section_path,heading_level,parent_heading,anchor_id,content,retrieval_synopsis,content_hash,index_generation_id,token_estimate,image_ids,metadata,embedding) select r.id,r.document_id,r.page_number,r.chunk_index,r.section_heading,r.section_path,r.heading_level,r.parent_heading,r.anchor_id,r.content,r.retrieval_synopsis,r.content_hash,r.index_generation_id,r.token_estimate,r.image_ids,r.metadata,r.embedding
      from jsonb_populate_record(null::public.document_chunks,v_row) r;
  end loop;
  if jsonb_typeof(p_images) is distinct from 'array' or jsonb_array_length(p_images) > 500 then raise exception 'invalid_ingestion_artifact_batch'; end if;
  for v_row in select value from jsonb_array_elements(p_images) loop
    if v_row->>'document_id' is distinct from v_document_id::text then raise exception 'ingestion_artifact_document_mismatch'; end if;
    perform public.assert_ingestion_artifact_sources(v_row,v_document_id,p_generation,null);
    if coalesce(v_row->>'storage_path','') !~ ('^' || v_document_id::text || '/' || (p_fence->>'lease_token') || '/' || p_generation::text || '/[0-9a-f-]{36}\.(png|jpg|jpeg|webp)$') then raise exception 'ingestion_image_path_mismatch'; end if;
    v_row := jsonb_build_object('id',gen_random_uuid(),'metadata','{}'::jsonb,'section_path','[]'::jsonb,'heading_path','[]'::jsonb,'image_ids','[]'::jsonb,'source_chunk_ids','[]'::jsonb,'source_image_ids','[]'::jsonb,'chunk_ids','[]'::jsonb,'tags','[]'::jsonb,'normalized_terms','[]'::jsonb,'token_estimate',0,'caption','','mime_type','image/png','image_type','unclear','searchable',true,'clinical_relevance_score',0,'source_kind','embedded','summary','','extraction_quality','unknown','confidence',0.5,'quality_score',0.7,'extraction_mode','deterministic') || v_row || jsonb_build_object('index_generation_id',p_generation,
      'metadata', coalesce(v_row->'metadata','{}'::jsonb) || jsonb_build_object('index_generation_id',p_generation,'ingestion_lease_token',p_fence->>'lease_token','ingestion_job_kind',p_fence->>'job_kind','ingestion_job_id',p_fence->>'job_id'));

    insert into public.document_images(id,document_id,page_number,storage_path,mime_type,caption,bbox,image_type,searchable,clinical_relevance_score,skip_reason,source_kind,width,height,image_hash,perceptual_hash,labels,index_generation_id,caption_confidence,clinical_priority_score,crop_completeness,image_quality_score,ocr_text_density,structured_extraction_confidence,visual_duplicate_group,metadata) select r.id,r.document_id,r.page_number,r.storage_path,r.mime_type,r.caption,r.bbox,r.image_type,r.searchable,r.clinical_relevance_score,r.skip_reason,r.source_kind,r.width,r.height,r.image_hash,r.perceptual_hash,r.labels,r.index_generation_id,r.caption_confidence,r.clinical_priority_score,r.crop_completeness,r.image_quality_score,r.ocr_text_density,r.structured_extraction_confidence,r.visual_duplicate_group,r.metadata
      from jsonb_populate_record(null::public.document_images,v_row) r;
  end loop;
  if jsonb_typeof(p_table_facts) is distinct from 'array' or jsonb_array_length(p_table_facts) > 500 then raise exception 'invalid_ingestion_artifact_batch'; end if;
  for v_row in select value from jsonb_array_elements(p_table_facts) loop
    if v_row->>'document_id' is distinct from v_document_id::text then raise exception 'ingestion_artifact_document_mismatch'; end if;
    perform public.assert_ingestion_artifact_sources(v_row,v_document_id,p_generation,null);

    v_row := jsonb_build_object('id',gen_random_uuid(),'metadata','{}'::jsonb,'section_path','[]'::jsonb,'heading_path','[]'::jsonb,'image_ids','[]'::jsonb,'source_chunk_ids','[]'::jsonb,'source_image_ids','[]'::jsonb,'chunk_ids','[]'::jsonb,'tags','[]'::jsonb,'normalized_terms','[]'::jsonb,'token_estimate',0,'caption','','mime_type','image/png','image_type','unclear','searchable',true,'clinical_relevance_score',0,'source_kind','embedded','summary','','extraction_quality','unknown','confidence',0.5,'quality_score',0.7,'extraction_mode','deterministic') || v_row || jsonb_build_object('owner_id',v_locked->'document'->'owner_id','index_generation_id',p_generation,
      'metadata', coalesce(v_row->'metadata','{}'::jsonb) || jsonb_build_object('index_generation_id',p_generation,'ingestion_lease_token',p_fence->>'lease_token','ingestion_job_kind',p_fence->>'job_kind','ingestion_job_id',p_fence->>'job_id'));

    insert into public.document_table_facts(id,owner_id,document_id,source_chunk_id,source_image_id,page_number,table_title,row_label,clinical_parameter,threshold_value,action,normalized_terms,index_generation_id,metadata) select r.id,r.owner_id,r.document_id,r.source_chunk_id,r.source_image_id,r.page_number,r.table_title,r.row_label,r.clinical_parameter,r.threshold_value,r.action,r.normalized_terms,r.index_generation_id,r.metadata
      from jsonb_populate_record(null::public.document_table_facts,v_row) r;
  end loop;
  if jsonb_typeof(p_embedding_fields) is distinct from 'array' or jsonb_array_length(p_embedding_fields) > 500 then raise exception 'invalid_ingestion_artifact_batch'; end if;
  for v_row in select value from jsonb_array_elements(p_embedding_fields) loop
    if v_row->>'document_id' is distinct from v_document_id::text then raise exception 'ingestion_artifact_document_mismatch'; end if;
    perform public.assert_ingestion_artifact_sources(v_row,v_document_id,p_generation,null);

    v_row := jsonb_build_object('id',gen_random_uuid(),'metadata','{}'::jsonb,'section_path','[]'::jsonb,'heading_path','[]'::jsonb,'image_ids','[]'::jsonb,'source_chunk_ids','[]'::jsonb,'source_image_ids','[]'::jsonb,'chunk_ids','[]'::jsonb,'tags','[]'::jsonb,'normalized_terms','[]'::jsonb,'token_estimate',0,'caption','','mime_type','image/png','image_type','unclear','searchable',true,'clinical_relevance_score',0,'source_kind','embedded','summary','','extraction_quality','unknown','confidence',0.5,'quality_score',0.7,'extraction_mode','deterministic') || v_row || jsonb_build_object('owner_id',v_locked->'document'->'owner_id','index_generation_id',p_generation,
      'metadata', coalesce(v_row->'metadata','{}'::jsonb) || jsonb_build_object('index_generation_id',p_generation,'ingestion_lease_token',p_fence->>'lease_token','ingestion_job_kind',p_fence->>'job_kind','ingestion_job_id',p_fence->>'job_id'));
    v_row := v_row || jsonb_build_object('embedding',(v_row->'embedding')::text);
    insert into public.document_embedding_fields(id,owner_id,document_id,source_chunk_id,field_type,content,content_hash,embedding,index_generation_id,metadata) select r.id,r.owner_id,r.document_id,r.source_chunk_id,r.field_type,r.content,r.content_hash,r.embedding,r.index_generation_id,r.metadata
      from jsonb_populate_record(null::public.document_embedding_fields,v_row) r;
  end loop;
  if jsonb_typeof(p_index_units) is distinct from 'array' or jsonb_array_length(p_index_units) > 500 then raise exception 'invalid_ingestion_artifact_batch'; end if;
  for v_row in select value from jsonb_array_elements(p_index_units) loop
    if v_row->>'document_id' is distinct from v_document_id::text then raise exception 'ingestion_artifact_document_mismatch'; end if;
    perform public.assert_ingestion_artifact_sources(v_row,v_document_id,p_generation,null);

    v_row := jsonb_build_object('id',gen_random_uuid(),'metadata','{}'::jsonb,'section_path','[]'::jsonb,'heading_path','[]'::jsonb,'image_ids','[]'::jsonb,'source_chunk_ids','[]'::jsonb,'source_image_ids','[]'::jsonb,'chunk_ids','[]'::jsonb,'tags','[]'::jsonb,'normalized_terms','[]'::jsonb,'token_estimate',0,'caption','','mime_type','image/png','image_type','unclear','searchable',true,'clinical_relevance_score',0,'source_kind','embedded','summary','','extraction_quality','unknown','confidence',0.5,'quality_score',0.7,'extraction_mode','deterministic') || v_row || jsonb_build_object('owner_id',v_locked->'document'->'owner_id','index_generation_id',p_generation,'producer','local-worker','artifact_generation_id',p_generation,
      'metadata', coalesce(v_row->'metadata','{}'::jsonb) || jsonb_build_object('index_generation_id',p_generation,'ingestion_lease_token',p_fence->>'lease_token','ingestion_job_kind',p_fence->>'job_kind','ingestion_job_id',p_fence->>'job_id'));
    v_row := v_row || jsonb_build_object('embedding',(v_row->'embedding')::text);
    insert into public.document_index_units(id,owner_id,document_id,unit_type,source_chunk_id,source_image_id,page_start,page_end,heading_path,title,content,normalized_terms,source_span,quality_score,extraction_mode,index_generation_id,producer,artifact_generation_id,embedding,metadata) select r.id,r.owner_id,r.document_id,r.unit_type,r.source_chunk_id,r.source_image_id,r.page_start,r.page_end,r.heading_path,r.title,r.content,r.normalized_terms,r.source_span,r.quality_score,r.extraction_mode,r.index_generation_id,r.producer,r.artifact_generation_id,r.embedding,r.metadata
      from jsonb_populate_record(null::public.document_index_units,v_row) r;
  end loop;
  return jsonb_build_object('ok',true);
end $$;

create or replace function public.read_ingestion_prepared_supplier_artifacts(p_fence jsonb, p_generation uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  c ingestion_generation_evidence.candidates;
  result jsonb;
  transport_limit constant bigint := 16777216;
begin

  if p_fence->>'version'='managed-native-parent-closure-read-v1' then
    if not ingestion_generation_evidence.keys(p_fence,array['version','fence','expectedPlanDigest'])
      or not ingestion_generation_evidence.visual_unit_fence(p_fence->'fence') then raise exception 'managed_native_parent_closure_invalid_packet';end if;
    return ingestion_generation_evidence.read_native_parent_closure(p_fence->'fence',p_generation,p_fence->>'expectedPlanDigest');
  end if;
    if p_generation is null
    or not ingestion_generation_evidence.keys(p_fence, array['job_kind','job_id','document_id','worker_id','lease_token','expected_generation_id','authority_digest'])
    or p_fence->>'job_kind' is distinct from 'node'
    or coalesce(p_fence->>'worker_id','') = ''
    or coalesce(p_fence->>'authority_digest','') !~ '^sha256:[0-9a-f]{64}$'
    then raise exception 'prepared_supplier_readback_invalid_fence'; end if;
  -- lock_candidate checks current attempt/source authority and the candidate's FIRST lease.
  c := ingestion_generation_evidence.lock_candidate(p_fence, p_generation);
  if c is null then return jsonb_build_object('ok',false,'reason','lease_lost'); end if;
  if coalesce((select sum(octet_length(a.artifact_bytes)::bigint)*2
      from ingestion_generation_evidence.retained_artifacts a
      where a.document_id=c.document_id and a.generation_id=c.generation_id),0) > transport_limit
    then raise exception 'prepared_supplier_readback_transport_limit_exceeded'; end if;
  if exists (
    select 1 from ingestion_generation_evidence.retained_artifacts a
    left join ingestion_generation_evidence.unit_declarations u
      on u.document_id=a.document_id and u.generation_id=a.generation_id
      and u.family=a.family and u.unit_key=a.unit_key
    where a.document_id=c.document_id and a.generation_id=c.generation_id and (
      u.declaration is null or a.group_key is distinct from u.declaration->>'groupKey'
      or a.representation is distinct from u.declaration->>'representation'
      or a.source_sha256 is distinct from c.source_sha256
      or a.byte_length is distinct from octet_length(a.artifact_bytes)::bigint
      or a.sha256 is distinct from 'sha256:'||encode(extensions.digest(a.artifact_bytes,'sha256'),'hex'))
  ) then raise exception 'prepared_supplier_readback_artifact_identity_mismatch'; end if;
  result := jsonb_build_object('ok',true,'managed',true,'preparedSupplierArtifacts',jsonb_build_object(
    'version','ingestion-prepared-supplier-artifacts-v1',
    'identity',jsonb_build_object('documentId',c.document_id,'ownerId',c.source_snapshot->>'owner_id',
      'generationId',c.generation_id,'jobId',c.job_id,'firstLeaseToken',c.first_lease_token,
      'authorityDigest',c.authority_digest,'sourceSha256',c.source_sha256,
      'sourceByteLength',c.source_byte_length,'sourceExpectationDigest',c.source_expectation_digest),
    'inventory',ingestion_generation_evidence.inventory(c),
    'artifacts',coalesce((select jsonb_agg(jsonb_build_object(
      'unitId',jsonb_build_object('family',a.family,'key',a.unit_key),
      'groupKey',a.group_key,'representation',a.representation,
      'sha256',a.sha256,'byteLength',a.byte_length,'locator',a.locator,
      'bytesHex',encode(a.artifact_bytes,'hex')) order by a.family,a.unit_key)
      from ingestion_generation_evidence.retained_artifacts a
      where a.document_id=c.document_id and a.generation_id=c.generation_id),'[]'::jsonb)));
  if octet_length(convert_to(result::text,'UTF8'))::bigint > transport_limit
    then raise exception 'prepared_supplier_readback_transport_limit_exceeded'; end if;
  return result;
end $$;
-- Apply only after reviewed native-retention-forward.candidate.sql; atomic transaction required.

set local lock_timeout='5s';

set local statement_timeout='60s';

do $$ begin
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='admin_pdf_blob') then raise exception 'pdf_append_existing_function_admin_pdf_blob';end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='admin_pdf_ref') then raise exception 'pdf_append_existing_function_admin_pdf_ref';end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='admin_pdf_fixed_evidence') then raise exception 'pdf_append_existing_function_admin_pdf_fixed_evidence';end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='admin_pdf_evaluate') then raise exception 'pdf_append_existing_function_admin_pdf_evaluate';end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='admin_pdf_commit_allowed') then raise exception 'pdf_append_existing_function_admin_pdf_commit_allowed';end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ingestion_generation_evidence' and p.proname='complete_admin_pdf') then raise exception 'pdf_append_existing_function_complete_admin_pdf';end if;
if to_regprocedure('public.site_content_canonical_json(jsonb)') is null then raise exception 'pdf_append_canonical_json_missing';end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.complete_managed_admin_text(jsonb,uuid,jsonb,boolean)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'pdf_append_preimage_complete_managed_admin_text';end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.read_ingestion_prepared_supplier_artifacts(jsonb,uuid)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'pdf_append_preimage_read_ingestion_prepared_supplier_artifacts';end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.commit_document_index_generation(jsonb,uuid,integer,integer,integer,jsonb,jsonb,jsonb)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'pdf_append_preimage_commit_document_index_generation';end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.complete_ingestion_job(jsonb,uuid,text)') and prosrc is not distinct from convert_from(decode('','hex'),'UTF8') and prosecdef and proowner='postgres'::regrole) then raise exception 'pdf_append_preimage_complete_ingestion_job';end if;
end $$;

-- Internal, fixed-source PDF evidence and terminal helpers; no new RPC signatures or grants.
create function ingestion_generation_evidence.admin_pdf_blob(p jsonb)
returns bytea language plpgsql immutable set search_path='' as $$
declare b bytea;
begin
 if not ingestion_generation_evidence.keys(p,array['bytesHex','sha256','byteLength'])
  or jsonb_typeof(p->'bytesHex') is distinct from 'string' or coalesce(p->>'bytesHex','') !~ '^([0-9a-f]{2})+$'
  or jsonb_typeof(p->'sha256') is distinct from 'string' or coalesce(p->>'sha256','') !~ '^sha256:[0-9a-f]{64}$'
  or jsonb_typeof(p->'byteLength') is distinct from 'number' or coalesce(p->>'byteLength','') !~ '^[1-9][0-9]*$'
  then raise exception 'managed_admin_pdf_invalid_blob';end if;
 b:=decode(p->>'bytesHex','hex');
 if octet_length(b)>2097152 or octet_length(b)::bigint<>(p->>'byteLength')::bigint
  or p->>'sha256'<>'sha256:'||encode(extensions.digest(b,'sha256'),'hex') then raise exception 'managed_admin_pdf_blob_digest';end if;
 return b;
end $$;

create function ingestion_generation_evidence.admin_pdf_ref(b bytea)
returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('bytesHex',encode(b,'hex'),'sha256','sha256:'||encode(extensions.digest(b,'sha256'),'hex'),'byteLength',octet_length(b))
$$;

create function ingestion_generation_evidence.admin_pdf_fixed_evidence(c ingestion_generation_evidence.candidates,n jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare a jsonb; ad public.document_admission_events; j public.ingestion_jobs; row jsonb; ref jsonb; comparison jsonb;
 capture_blob ingestion_generation_evidence.retained_artifacts; provenance ingestion_generation_evidence.retained_artifacts;
 safety jsonb; profile jsonb; original ingestion_generation_evidence.retained_artifacts; witness ingestion_generation_evidence.retained_artifacts;
begin
 if c.source_sha256<>'sha256:abbc8107a09582e18f36bf4905c75f1fc78af70cd516851b89bff8919ca5bece' or c.source_byte_length<>2211561 or c.source_expectation_digest<>'sha256:2a5c6ae064ef159f15042105c85edc9da4af6bd231ae1268e703baf0c447e0da'
  or n->'identity'->>'documentId' is distinct from c.document_id::text or n->'identity'->>'generationId' is distinct from c.generation_id::text
  or n->'sourceAssessment' is distinct from '"unverified"'::jsonb or n->'activated' is distinct from 'false'::jsonb
  then raise exception 'managed_admin_pdf_fixed_source_required';end if;
 a:=public.lock_ingestion_document_authority(c.document_id,false);
 if a is null or a->>'authority_digest' is distinct from c.authority_digest
  or a->'document'->'owner_id' is distinct from c.source_snapshot->'owner_id'
  or a->'document'->>'file_type' is distinct from 'application/pdf' or a->'document'->>'content_hash' is distinct from substring(c.source_sha256 from 8)
  or (a->'document'->>'file_size')::bigint is distinct from c.source_byte_length then raise exception 'managed_admin_pdf_current_authority_required';end if;
 select * into strict j from public.ingestion_jobs where id=c.job_id;
 select * into ad from public.document_admission_events where id=(a->'document'->'metadata'->>'admission_event_id')::uuid;
 if not found or ad.actor_kind is distinct from 'administrator' or ad.source_channel is distinct from 'admin_api'
  or ad.document_id is distinct from c.document_id or ad.staging_owner_id::text is distinct from a->'document'->>'owner_id'
  or ad.content_sha256 is distinct from c.source_sha256 or ad.byte_count is distinct from c.source_byte_length
  or ad.mime_type is distinct from 'application/pdf' or ad.admission_policy_version is distinct from 'trusted-document-admission-v1'
  or ad.authority is distinct from a->'document'->'metadata'->'authority'
  or c.source_snapshot->'metadata'->'admission_event_id' is distinct from a->'document'->'metadata'->'admission_event_id'
  or ad.file_name_sha256 is distinct from 'sha256:'||encode(extensions.digest(convert_to(a->'document'->>'file_name','UTF8'),'sha256'),'hex')
  or ad.storage_path_sha256 is distinct from 'sha256:'||encode(extensions.digest(convert_to(a->'document'->>'storage_path','UTF8'),'sha256'),'hex')
  or ad.authority->>'authorityBasis' is distinct from 'administrator_template'
  or ad.authority->>'licencePolicy' is distinct from 'public_index_permitted'
  or ad.authority->>'providerProcessing' is distinct from 'permitted' or ad.authority->>'purpose' is distinct from 'clinical_retrieval'
  or ad.authority->>'currentness' is distinct from 'current'
  or not coalesce(ad.authority->'supportedFeatures' @> '["text"]'::jsonb,false)
  or (ad.authority->>'effectiveDate')::date>current_date or (ad.authority->>'expiryDate')::date<=current_date
  or (ad.authority->>'reviewDate')::date<=current_date
  then raise exception 'managed_admin_pdf_current_admission_required';end if;
 select * into strict original from ingestion_generation_evidence.retained_artifacts
  where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='original-source';
 select * into strict witness from ingestion_generation_evidence.retained_artifacts
  where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='original-source-expectation-witness';
 if original.sha256 is distinct from c.source_sha256 or original.byte_length<>2211561 or original.representation<>'original_binary'
  or original.sha256<>'sha256:'||encode(extensions.digest(original.artifact_bytes,'sha256'),'hex')
  or witness.sha256<>'sha256:0f96a882972cc3898cd0428efa2b648eae777e0158f2d23682efe5e4514c14b8' or witness.source_sha256<>c.source_sha256 or witness.representation<>'source_expectation_witness'
  or witness.sha256<>'sha256:'||encode(extensions.digest(witness.artifact_bytes,'sha256'),'hex')
  then raise exception 'managed_admin_pdf_retained_original_required';end if;
 select x.value into strict row from jsonb_array_elements(n->'rows') x where x.value->>'family'='images' and x.value->'row'->>'source_kind'='table_crop';
 select * into strict capture_blob from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id
  and family='private_objects' and unit_key='image:'||(row->'row'->>'capture_ordinal')||':binary';
 select * into strict provenance from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id
  and family='private_objects' and unit_key='image:'||(row->'row'->>'capture_ordinal')||':provenance';
 if capture_blob.sha256<>'sha256:fd7a4d16b41d1856e64759540ce37cf55bc90b247f50424643cdc3c01fc3a14f' or capture_blob.byte_length<>104496 or capture_blob.representation<>'image_binary'
  or capture_blob.sha256<>'sha256:'||encode(extensions.digest(capture_blob.artifact_bytes,'sha256'),'hex')
  or provenance.representation<>'image_provenance' or provenance.source_sha256<>c.source_sha256
  or provenance.byte_length<>octet_length(provenance.artifact_bytes)
  or provenance.sha256<>'sha256:'||encode(extensions.digest(provenance.artifact_bytes,'sha256'),'hex')
  or row->'row'->'descriptor' is distinct from '{"bbox":[68,315.77,526.71,599.3],"height":868,"metadata":{"accessible_table_markdown":"| Drinking frequency | Risk level |  |  |  |\n| --- | --- | --- | --- | --- |\n|  | 0.1% (1 in 1000) | 0.2% (1 in 500) | 1% (1 in 100) | 2% (1 in 50) |\n| Men | Standard drinks (per week) |  |  |  |\n| Daily | 18.5 | 18.7 | 20.2 | 21.9 |\n| 6 days/week | 17.1 | 17.2 | 18.6 | 20.2 |\n| 5 days/week | 15.5 | 15.7 | 16.9 | 18.5 |\n| 4 days/week | 13.6 | 13.7 | 14.9 | 16.4 |\n| 3 days/week | 11.3 | 11.4 | 12.5 | 13.8 |\n| 2 days/week | 8 | 8.1 | 9 | 10.1 |\n| 1 day/week | 3.4 | 3.4 | 4.1 | 4.9 |\n| Women | Standard drinks (per week) |  |  |  |\n| Daily | 14 | 14.1 | 15.3 | 16.7 |\n| 6 days/week | 13.3 | 13.4 | 14.5 | 15.8 |\n| 5 days/week | 12.3 | 12.5 | 13.5 | 14.8 |\n| 4 days/week | 11.1 | 11.2 | 12.1 | 13.3 |\n| 3 days/week | 9.5 | 9.6 | 10.5 | 11.6 |\n| 2 days/week | 7 | 7.1 | 7.8 | 8.8 |\n| 1 day/week | 4.1 | 4.1 | 4.7 | 5.4 |","bbox":[68,315.77,526.71,599.3],"candidate_type":"table","clip_bbox":[68,315.77,526.71,599.3],"column_count":5,"crop_completeness":1,"crop_touches_page_edge":false,"extraction_method":"pymupdf_find_tables","heading_text":"Table A2.1 Number of standard drinks per week associated with alternative lifetime mortality risk thresholds, depending on number of days alcohol is consumed per week","pageNumber":4,"page_height":841.89,"page_rotation":0,"page_width":595.28,"render_dpi":220,"render_scale":3.056,"row_count":18,"rows_truncated":false,"source_kind":"table_crop","source_regions":[{"bbox":[68,315.77,526.71,599.3],"page_number":4,"source_kind":"table_crop"}],"table_columns":["Drinking frequency","Risk level","","",""],"table_confidence":0.99,"table_index":1,"table_label":"Table A2.1","table_role":"clinical","table_rows":[["Drinking frequency","Risk level","","",""],["","0.1% (1 in 1000)","0.2% (1 in 500)","1% (1 in 100)","2% (1 in 50)"],["Men","Standard drinks (per week)","","",""],["Daily","18.5","18.7","20.2","21.9"],["6 days/week","17.1","17.2","18.6","20.2"],["5 days/week","15.5","15.7","16.9","18.5"],["4 days/week","13.6","13.7","14.9","16.4"],["3 days/week","11.3","11.4","12.5","13.8"],["2 days/week","8","8.1","9","10.1"],["1 day/week","3.4","3.4","4.1","4.9"],["Women","Standard drinks (per week)","","",""],["Daily","14","14.1","15.3","16.7"],["6 days/week","13.3","13.4","14.5","15.8"],["5 days/week","12.3","12.5","13.5","14.8"],["4 days/week","11.1","11.2","12.1","13.3"],["3 days/week","9.5","9.6","10.5","11.6"],["2 days/week","7","7.1","7.8","8.8"],["1 day/week","4.1","4.1","4.7","5.4"]],"table_text":"| Drinking frequency | Risk level |  |  |  |\n| --- | --- | --- | --- | --- |\n|  | 0.1% (1 in 1000) | 0.2% (1 in 500) | 1% (1 in 100) | 2% (1 in 50) |\n| Men | Standard drinks (per week) |  |  |  |\n| Daily | 18.5 | 18.7 | 20.2 | 21.9 |\n| 6 days/week | 17.1 | 17.2 | 18.6 | 20.2 |\n| 5 days/week | 15.5 | 15.7 | 16.9 | 18.5 |\n| 4 days/week | 13.6 | 13.7 | 14.9 | 16.4 |\n| 3 days/week | 11.3 | 11.4 | 12.5 | 13.8 |\n| 2 days/week | 8 | 8.1 | 9 | 10.1 |\n| 1 day/week | 3.4 | 3.4 | 4.1 | 4.9 |\n| Women | Standard drinks (per week) |  |  |  |\n| Daily | 14 | 14.1 | 15.3 | 16.7 |\n| 6 days/week | 13.3 | 13.4 | 14.5 | 15.8 |\n| 5 days/week | 12.3 | 12.5 | 13.5 | 14.8 |\n| 4 days/week | 11.1 | 11.2 | 12.1 | 13.3 |\n| 3 days/week | 9.5 | 9.6 | 10.5 | 11.6 |\n| 2 days/week | 7 | 7.1 | 7.8 | 8.8 |\n| 1 day/week | 4.1 | 4.1 | 4.7 | 5.4 |","table_title":"Number of standard drinks per week associated with alternative lifetime mortality risk thresholds, depending on number of days alcohol is consumed per week"},"mimeType":"image/png","pageNumber":4,"sourceKind":"table_crop","width":1403}'::jsonb
  or not exists(select 1 from jsonb_array_elements((convert_from(ingestion_generation_evidence.admin_pdf_blob(row->'receipt'),'UTF8')::jsonb)->'retainedReferences') x where x.value->>'sha256'=provenance.sha256)
  then raise exception 'managed_admin_pdf_actual_visual_binding_required';end if;
 -- Native validation already authenticates the complete actual provenance body, binary dependency and source/page descriptor.
 -- This final binding reuses the independently accepted exact pixels; no new visual judgement is inferred.
 comparison:=jsonb_build_object('version','four-page-pilot-table-visual-comparison-v1','decision','accepted',
  'sourceSha256',c.source_sha256,'pilotPage',4,'parentPhysicalPage',62,'imageSha256',capture_blob.sha256,
  'provenanceSha256',provenance.sha256,'pixelReviewSha256','sha256:ead8fa223ce354b77526e499721458fbc28b4bccb64af716ed13aa5bdbe24028',
  'qualification','existing accepted pixels plus server-checked actual retained provenance; no new clinical approval');
 safety:=jsonb_build_object('version','managed-admin-pdf-current-admission-v1','documentId',c.document_id,'ownerId',c.source_snapshot->'owner_id',
  'generationId',c.generation_id,'jobId',c.job_id,'firstLeaseToken',c.first_lease_token,'authorityDigest',c.authority_digest,
  'sourceSha256',c.source_sha256,'sourceByteLength',c.source_byte_length,'admissionEvent',to_jsonb(ad),
  'safetyScope','exact hash-pinned public source plus authentic current administrator admission; no generic scan or clinical approval');
 profile:=jsonb_build_object('version','managed-admin-pdf-fixed-profile-v1','profileId','nhmrc-ds14-four-page-native-pilot-v1',
  'sourceSha256',c.source_sha256,'sourceExpectationPin','sha256:8fe858fddf8d36bee746d66fb8ed85ef0a0ecd6e9b4975e085c5d93be635acb0','witnessPin','sha256:0f96a882972cc3898cd0428efa2b648eae777e0158f2d23682efe5e4514c14b8','frozenPin','sha256:119422cdb8fa98821bec9bdec738685300213f24ef2264c5edea43346c32cfcf',
  'sourceAssessmentPin','sha256:186a990428afaf846d308715312ffdcab4da89b0c786e5d20928156d70419d86','qualityReviewPin','sha256:e5ccaa420a246eadc33842153a28fd97e8d25af90648792fa3a30d684ecb6137','qualityReportPin','sha256:6cee827920bce16995b5768b7926242c1525c00400587d80753d568798f2de5c','pixelReviewPin','sha256:ead8fa223ce354b77526e499721458fbc28b4bccb64af716ed13aa5bdbe24028',
  'visualComparison',comparison,'identity',n->'identity','scope','whole_admitted_four_page_native_pdf_pilot',
  'rightsQualification','Table crop retained privately only. Cover, NHMRC logo, Coat of Arms and identified third-party items gain no public asset or reuse authority.',
  'clinicalApproval','not_assessed','publicationApproval','not_granted','parentCompleteness','not_claimed');
 return jsonb_build_object('profileId','nhmrc-ds14-four-page-native-pilot-v1',
  'profileDigest','sha256:'||encode(extensions.digest(convert_to(public.site_content_canonical_json(profile),'UTF8'),'sha256'),'hex'),
  'visualComparisonRef',ingestion_generation_evidence.admin_pdf_ref(convert_to(public.site_content_canonical_json(comparison),'UTF8')),
  'safetyRef',ingestion_generation_evidence.admin_pdf_ref(convert_to(public.site_content_canonical_json(safety),'UTF8')),
  'tableRowId',row->'rowId','binaryRef',ingestion_generation_evidence.admin_pdf_ref(capture_blob.artifact_bytes),
  'provenanceRef',ingestion_generation_evidence.admin_pdf_ref(provenance.artifact_bytes),'profile',profile);
end $$;

create function ingestion_generation_evidence.admin_pdf_evaluate(c ingestion_generation_evidence.candidates,p jsonb,n jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare fixed jsonb; e jsonb; w jsonb; frozen jsonb; report jsonb; item jsonb; page jsonb; segment jsonb; row jsonb;
 required jsonb; expected_cells jsonb; role jsonb; d ingestion_generation_evidence.producer_declarations;
 optional jsonb:='[]'::jsonb; expected_ids jsonb; actual_ids jsonb; g jsonb; index integer:=0; byte_count integer; quality jsonb;
begin
 if not ingestion_generation_evidence.keys(p,array['version','identity','profileId','profileDigest','planDigest','nativePopulationDigest','sourceWitnessRef','sourceAssessmentRef','qualityReviewRef','evaluationRef','safetyRef','optionalEnrichment'])
  or p->>'version' is distinct from 'managed-admin-pdf-complete-v1' or p->>'profileId' is distinct from 'nhmrc-ds14-four-page-native-pilot-v1'
  or p->'identity' is distinct from n->'identity' or p->>'planDigest' is distinct from n->>'planDigest'
  or p->>'nativePopulationDigest' is distinct from n->>'sqlPopulationDigest'
  or octet_length(convert_to(p::text,'UTF8'))>2097152 then raise exception 'managed_admin_pdf_invalid_packet';end if;
 fixed:=ingestion_generation_evidence.admin_pdf_fixed_evidence(c,n);
 if p->>'profileDigest' is distinct from fixed->>'profileDigest' or p->'safetyRef' is distinct from fixed->'safetyRef'
  then raise exception 'managed_admin_pdf_untrusted_registration';end if;
 e:=convert_from(ingestion_generation_evidence.admin_pdf_blob(p->'evaluationRef'),'UTF8')::jsonb;
 if not ingestion_generation_evidence.keys(e,array['version','identity','profileId','profileDigest','planDigest','nativePopulationDigest','sourceExpectationRef','witnessRef','frozenRef','sourceFamilyAssessmentRef','qualityReviewRef','qualityReportRef','pageCoverage','sourceRoleMappings','tableCells','visualComparisonRef','safetyRef','optionalEnrichment'])
  or e->>'version' is distinct from 'managed-admin-pdf-evaluation-v1' or e->'identity' is distinct from p->'identity'
  or e->'profileId' is distinct from p->'profileId' or e->'profileDigest' is distinct from p->'profileDigest'
  or e->'planDigest' is distinct from p->'planDigest' or e->'nativePopulationDigest' is distinct from p->'nativePopulationDigest'
  or e->'witnessRef' is distinct from p->'sourceWitnessRef' or e->'sourceFamilyAssessmentRef' is distinct from p->'sourceAssessmentRef'
  or e->'qualityReviewRef' is distinct from p->'qualityReviewRef' or e->'safetyRef' is distinct from p->'safetyRef'
  or e->'visualComparisonRef' is distinct from fixed->'visualComparisonRef'
  or e->'optionalEnrichment' is distinct from p->'optionalEnrichment' then raise exception 'managed_admin_pdf_evaluation_binding';end if;
 for item in select jsonb_build_object('key',key,'value',value) from jsonb_each('{"sourceExpectationRef":"sha256:8fe858fddf8d36bee746d66fb8ed85ef0a0ecd6e9b4975e085c5d93be635acb0","witnessRef":"sha256:0f96a882972cc3898cd0428efa2b648eae777e0158f2d23682efe5e4514c14b8","frozenRef":"sha256:119422cdb8fa98821bec9bdec738685300213f24ef2264c5edea43346c32cfcf","sourceFamilyAssessmentRef":"sha256:186a990428afaf846d308715312ffdcab4da89b0c786e5d20928156d70419d86","qualityReviewRef":"sha256:e5ccaa420a246eadc33842153a28fd97e8d25af90648792fa3a30d684ecb6137","qualityReportRef":"sha256:6cee827920bce16995b5768b7926242c1525c00400587d80753d568798f2de5c"}'::jsonb) loop
  perform ingestion_generation_evidence.admin_pdf_blob(e->(item->>'key'));
  if e->(item->>'key')->>'sha256' is distinct from item->>'value' then raise exception 'managed_admin_pdf_reference_pin';end if;
 end loop;
 w:=convert_from(ingestion_generation_evidence.admin_pdf_blob(e->'witnessRef'),'UTF8')::jsonb;
 frozen:=convert_from(ingestion_generation_evidence.admin_pdf_blob(e->'frozenRef'),'UTF8')::jsonb;
 report:=convert_from(ingestion_generation_evidence.admin_pdf_blob(e->'qualityReportRef'),'UTF8')::jsonb;
 if convert_from(ingestion_generation_evidence.admin_pdf_blob(e->'sourceExpectationRef'),'UTF8')::jsonb is distinct from c.source_expectation
  then raise exception 'managed_admin_pdf_expectation_binding';end if;
 if jsonb_typeof(e->'pageCoverage') is distinct from 'array' or jsonb_array_length(e->'pageCoverage')<>4 then raise exception 'managed_admin_pdf_page_count';end if;
 for page in select value from jsonb_array_elements(e->'pageCoverage') loop
  index:=index+1;
  if not ingestion_generation_evidence.keys(page,array['pilotPage','parentPhysicalPage','parentPrintedPage','normalizationRule','segments'])
   or page->'pilotPage' is distinct from to_jsonb(index) or page->'parentPhysicalPage' is distinct from ('[9,10,11,62]'::jsonb)->(index-1)
   or page->'parentPrintedPage' is distinct from ('["4","5","6","57"]'::jsonb)->(index-1)
   or page->>'normalizationRule' is distinct from 'exact-current-accepted-report-bytes-v1' or jsonb_typeof(page->'segments') is distinct from 'array'
   or jsonb_array_length(page->'segments')<>1 then raise exception 'managed_admin_pdf_page_mapping';end if;
  segment:=page->'segments'->0;
  if not ingestion_generation_evidence.keys(segment,array['rowId','contentStart','contentEnd','referenceStart','referenceEnd'])
   or jsonb_typeof(segment->'rowId') is distinct from 'string' or coalesce(segment->>'rowId','') !~ '^[0-9a-f-]{36}$'
   then raise exception 'managed_admin_pdf_page_segment';end if;
  select x.value into strict row from jsonb_array_elements(n->'rows') x where x.value->>'family'='chunks' and x.value->>'rowId'=segment->>'rowId';
  byte_count:=octet_length(convert_to(report->'native'->'payload'->'pages'->(index-1)->>'text','UTF8'));
  if row->'row'->'page_number' is distinct from to_jsonb(index)
   or convert_to(row->'row'->>'content','UTF8') is distinct from convert_to(report->'native'->'payload'->'pages'->(index-1)->>'text','UTF8')
   or segment->'contentStart' is distinct from '0'::jsonb or segment->'referenceStart' is distinct from '0'::jsonb
   or segment->'contentEnd' is distinct from to_jsonb(byte_count) or segment->'referenceEnd' is distinct from to_jsonb(byte_count)
   then raise exception 'managed_admin_pdf_full_page_bytes';end if;
 end loop;
 select jsonb_agg(jsonb_build_object('family',g.value->>'family')||r.value) into required from jsonb_array_elements(w->'groups') g
  cross join lateral jsonb_array_elements(g.value->'population'->'requirements') r where g.value->>'family' in ('chunks','images');
 if jsonb_typeof(e->'sourceRoleMappings') is distinct from 'array' or jsonb_array_length(e->'sourceRoleMappings')<>62
  or (select count(distinct (value->>'family')||':'||(value->>'requirementId')) from jsonb_array_elements(e->'sourceRoleMappings'))<>62
  then raise exception 'managed_admin_pdf_role_population';end if;
 for item in select value from jsonb_array_elements(required) loop
  select value into strict role from jsonb_array_elements(e->'sourceRoleMappings') where value->>'family'=item->>'family' and value->>'requirementId'=item->>'id';
  if not ingestion_generation_evidence.keys(role,array['family','requirementId','sourceEvidenceIds','rowIds'])
   or role->'sourceEvidenceIds' is distinct from item->'sourceEvidenceIds' or jsonb_typeof(role->'rowIds') is distinct from 'array'
   or jsonb_array_length(role->'rowIds')<>1 then raise exception 'managed_admin_pdf_source_role_binding';end if;
  if item->>'family'='images' then
   if role->'rowIds' is distinct from jsonb_build_array(fixed->'tableRowId') then raise exception 'managed_admin_pdf_visual_role';end if;
  else
   index:=case when item->>'id' like 'pilot-native-page-%' then right(item->>'id',1)::integer else 4 end;
   if role->'rowIds' is distinct from jsonb_build_array(e->'pageCoverage'->(index-1)->'segments'->0->'rowId')
    then raise exception 'managed_admin_pdf_semantic_role';end if;
  end if;
 end loop;
 select jsonb_agg(jsonb_build_object('sex',r.value->'sex','frequency',r.value->'drinkingFrequency','percent',frozen->'table'->'riskColumns'->(v.ord::integer-1)->'percent',
  'ratio',frozen->'table'->'riskColumns'->(v.ord::integer-1)->'ratio','value',v.value,'unit',frozen->'table'->'unit') order by r.ord,v.ord)
  into expected_cells from jsonb_array_elements(frozen->'table'->'rows') with ordinality r(value,ord)
  cross join lateral jsonb_array_elements(r.value->'values') with ordinality v(value,ord);
 if jsonb_array_length(expected_cells)<>56 or e->'tableCells' is distinct from expected_cells then raise exception 'managed_admin_pdf_table_relations';end if;
 -- Account every actual optional declaration. Unknown/deferred is not converted into an empty generated population.
 for d in select * from ingestion_generation_evidence.producer_declarations where document_id=c.document_id and generation_id=c.generation_id
  and family in ('table_facts','embedding_fields','index_units') order by family collate "C",group_key collate "C" loop
  select value into strict g from jsonb_array_elements(p->'optionalEnrichment') where value->>'family'=d.family and value->>'groupKey'=d.group_key;
  expected_ids:=case when d.declaration->'population'->>'tag'='known' then d.declaration->'population'->'expectedUnits' else null end;
  select coalesce(jsonb_agg(x.value->'rowId' order by x.value->>'rowId'),'[]'::jsonb) into actual_ids from jsonb_array_elements(n->'rows') x where x.value->>'family'=d.family;
  if not ingestion_generation_evidence.keys(g,array['family','groupKey','state','producerManifestDigest','expectedUnitIds','persistedRowIds','reason'])
   or g->'producerManifestDigest' is distinct from d.declaration->'producer'->'outputManifestDigest'
   or g->'expectedUnitIds' is distinct from coalesce(expected_ids,'null'::jsonb) or g->'persistedRowIds' is distinct from actual_ids
   or g->>'state' is distinct from (case when expected_ids is not null then case when jsonb_array_length(actual_ids)>0 then 'persisted' else 'prepared_only' end else 'deferred' end)
   or (jsonb_array_length(actual_ids)>0 and jsonb_array_length(actual_ids)<>jsonb_array_length(expected_ids))
   then raise exception 'managed_admin_pdf_optional_population';end if;
  optional:=optional||jsonb_build_array(g);
 end loop;
 if p->'optionalEnrichment' is distinct from optional then raise exception 'managed_admin_pdf_optional_group_count';end if;
 return fixed;
end $$;

create function ingestion_generation_evidence.admin_pdf_commit_allowed(f jsonb,g uuid)
returns boolean language sql stable set search_path='' as $$
 select coalesce(current_setting('psychsift.admin_pdf_terminal_owner',true)=(f->>'document_id')||':'||(f->>'job_id'),false)
 and exists(select 1 from ingestion_generation_evidence.prerequisite_accounting s join ingestion_generation_evidence.candidates c using(document_id,generation_id)
  where c.document_id=(f->>'document_id')::uuid and c.generation_id=g and c.job_id=(f->>'job_id')::uuid and c.first_lease_token=(f->>'lease_token')::uuid
  and c.authority_digest=f->>'authority_digest' and c.source_sha256='sha256:abbc8107a09582e18f36bf4905c75f1fc78af70cd516851b89bff8919ca5bece' and s.snapshot->>'version'='managed-admin-pdf-seal-v1'
  and s.snapshot->'packet'->'identity'->>'jobId'=f->>'job_id' and s.snapshot->'packet'->'identity'->>'generationId'=g::text
  and s.snapshot_digest='sha256:'||encode(extensions.digest(convert_to(public.site_content_canonical_json(s.snapshot),'UTF8'),'sha256'),'hex')
  and (select count(*) from public.document_chunks r where r.document_id=c.document_id and r.index_generation_id=c.generation_id)=4
  and not exists(select 1 from ingestion_generation_evidence.managed_vector_chunk_rows cr left join public.document_chunks pr on pr.id=cr.id
   where cr.document_id=c.document_id and cr.index_generation_id=c.generation_id and (pr.id is null or
    (to_jsonb(pr)-array['created_at','search_tsv']) is distinct from
    (to_jsonb(jsonb_populate_record(null::public.document_chunks,to_jsonb(cr)))-array['created_at','search_tsv']))))
$$;

create function ingestion_generation_evidence.complete_admin_pdf(f jsonb,g uuid,p jsonb,read_only boolean)
returns jsonb language plpgsql set search_path='' as $$
declare c ingestion_generation_evidence.candidates; j public.ingestion_jobs; a jsonb; n jsonb; fixed jsonb;
 prior ingestion_generation_evidence.prerequisite_accounting; s jsonb; bytes bytea; h text; result jsonb; pages jsonb; quality jsonb;
 replay text; claim jsonb; identity jsonb; active_worker text; next_fence jsonb; checkpoint jsonb; checkpoint_bytes bytea; checkpoint_hash text;
begin
 if read_only is null or not ingestion_generation_evidence.visual_unit_fence(f) or g is null then raise exception 'managed_admin_pdf_invalid_fence';end if;
 a:=public.lock_ingestion_document_authority((f->>'document_id')::uuid,false);
 perform 1 from public.ingestion_jobs where document_id=(f->>'document_id')::uuid order by id for update;
 perform 1 from public.indexing_v3_agent_jobs where document_id=(f->>'document_id')::uuid order by id for update;
 select * into strict j from public.ingestion_jobs where id=(f->>'job_id')::uuid;
 select * into strict c from ingestion_generation_evidence.candidates where document_id=(f->>'document_id')::uuid and generation_id=g for update;
 select convert_from(artifact_bytes,'UTF8')::jsonb into strict claim from ingestion_generation_evidence.retained_artifacts
  where document_id=c.document_id and generation_id=c.generation_id and family='attempt_control' and unit_key='claim_checkpoint';
 active_worker:=claim->>'workerId';
 identity:=jsonb_build_object('documentId',c.document_id,'generationId',c.generation_id,'jobId',c.job_id,'workerId',active_worker,
  'firstLeaseToken',c.first_lease_token,'attemptNumber',j.attempt_count,'batchId',j.batch_id,'authorityDigest',c.authority_digest,
  'predecessorGenerationId',c.predecessor_generation_id,'ownerId',c.source_snapshot->'owner_id','sourceSha256',c.source_sha256,
  'sourceByteLength',c.source_byte_length,'sourceExpectationDigest',c.source_expectation_digest);
 if a is null or p->'identity' is distinct from identity or c.job_id is distinct from j.id or j.document_id is distinct from c.document_id
  or j.lease_token is distinct from c.first_lease_token or c.first_lease_token::text is distinct from f->>'lease_token'
  or active_worker is distinct from f->>'worker_id' or j.lease_write_generation_id is distinct from g
  or c.predecessor_generation_id is distinct from (f->>'expected_generation_id')::uuid
  or c.authority_digest is distinct from f->>'authority_digest' or a->>'authority_digest' is distinct from c.authority_digest
  or j.lease_authority_digest is distinct from c.authority_digest
  or exists(select 1 from public.ingestion_jobs o where o.document_id=c.document_id and o.id<>j.id and (o.created_at>j.created_at or o.status in ('pending','processing')))
  then raise exception 'managed_admin_pdf_identity_mismatch';end if;
 if j.status='completed' then
  if j.stage<>'admin_pdf_completed' or j.locked_by is not null or j.lease_expires_at is not null or j.next_run_at is not null
   or j.lease_expected_generation_id is distinct from g or (a->'document'->>'index_generation_id')::uuid is distinct from g
   then raise exception 'managed_admin_pdf_replay_state';end if;
 else
  if read_only or j.status<>'processing' or j.locked_by is distinct from active_worker or j.lease_expires_at<=clock_timestamp()
   or (a->'document'->>'index_generation_id')::uuid is distinct from c.predecessor_generation_id
   or public.assert_current_ingestion_attempt(f,g) is null then raise exception 'managed_admin_pdf_current_attempt_required';end if;
 end if;
 n:=ingestion_generation_evidence.checked_native_parent_closure(c,p->>'planDigest')->'managedNativeParentClosure';
 fixed:=ingestion_generation_evidence.admin_pdf_evaluate(c,p,n);
 s:=jsonb_build_object('version','managed-admin-pdf-seal-v1','packet',p,'identity',identity,'scope','whole_admitted_four_page_native_pdf_pilot',
  'profileId',p->'profileId','profileDigest',fixed->'profileDigest','sourceAssessmentDigest',p->'sourceAssessmentRef'->'sha256',
  'evaluationDigest',p->'evaluationRef'->'sha256','nativePopulationDigest',n->'sqlPopulationDigest',
  'requiredCoverage',jsonb_build_object('nativePages',4,'semanticRequirements',61,'tableCells',56,'tableVisualRequirements',1),
  'optionalEnrichment',p->'optionalEnrichment','activated',true,'clinicalApproval','not_assessed','publicationApproval','not_granted',
  'parentCompleteness','not_claimed','completionRevision','fixed-four-page-native-v1');
 bytes:=convert_to(public.site_content_canonical_json(s),'UTF8');h:='sha256:'||encode(extensions.digest(bytes,'sha256'),'hex');
 checkpoint:=claim||jsonb_build_object('phase','preseal','terminalVersion','managed-admin-pdf-complete-v1','terminalPacket',p);
 checkpoint_bytes:=convert_to(public.site_content_canonical_json(checkpoint),'UTF8');
 checkpoint_hash:='sha256:'||encode(extensions.digest(checkpoint_bytes,'sha256'),'hex');
 if j.status='completed' then
  select * into strict prior from ingestion_generation_evidence.prerequisite_accounting where document_id=c.document_id and generation_id=g and snapshot->>'version'='managed-admin-pdf-seal-v1';
  if prior.snapshot is distinct from s or prior.snapshot_digest is distinct from h
   or (select count(*) from public.document_chunks where document_id=c.document_id and index_generation_id=g)<>4
   or exists(select 1 from ingestion_generation_evidence.managed_vector_chunk_rows cr left join public.document_chunks pr on pr.id=cr.id
    where cr.document_id=c.document_id and cr.index_generation_id=g and (pr.id is null or (to_jsonb(pr)-array['created_at','search_tsv']) is distinct from (to_jsonb(jsonb_populate_record(null::public.document_chunks,to_jsonb(cr)))-array['created_at','search_tsv'])))
   or (select count(*) from public.document_pages where document_id=c.document_id and index_generation_id=g)<>4
   or exists(select 1 from public.document_pages pr join ingestion_generation_evidence.managed_vector_chunk_rows cr on cr.document_id=pr.document_id and cr.index_generation_id=pr.index_generation_id and cr.page_number=pr.page_number where pr.document_id=c.document_id and pr.index_generation_id=g and (pr.text is distinct from cr.content or pr.ocr_used))
   or not exists(select 1 from public.document_index_quality where document_id=c.document_id and owner_id=(identity->>'ownerId')::uuid and quality_score=1 and extraction_quality='good' and metrics->>'admin_pdf_seal_digest'=h)
   or not exists(select 1 from ingestion_generation_evidence.retained_artifacts r join ingestion_generation_evidence.outcomes o using(document_id,generation_id,family,unit_key)
    where r.document_id=c.document_id and r.generation_id=g and r.family='attempt_control' and r.unit_key='preseal_checkpoint'
    and r.artifact_bytes=checkpoint_bytes and r.sha256=checkpoint_hash and o.outcome->>'artifactSha256'=checkpoint_hash and o.outcome->>'disposition'='retained')
   then raise exception 'managed_admin_pdf_replay_mismatch';end if;
  replay:='already_completed';
 else
  if public.assert_current_ingestion_attempt(f,g) is null then raise exception 'managed_admin_pdf_current_attempt_required';end if;
  if exists(select 1 from ingestion_generation_evidence.prerequisite_accounting where document_id=c.document_id and generation_id=g and snapshot->>'version'='managed-admin-pdf-seal-v1')
   then raise exception 'managed_admin_pdf_seal_collision';end if;
  if not exists(select 1 from ingestion_generation_evidence.unit_declarations where document_id=c.document_id and generation_id=g and family='attempt_control' and unit_key='preseal_checkpoint'
    and declaration->'dependencies'='[{"family":"attempt_control","key":"claim_checkpoint"},{"family":"private_objects","key":"original-source"}]'::jsonb)
    then raise exception 'managed_admin_pdf_preseal_declaration_required';end if;
  insert into ingestion_generation_evidence.retained_artifacts(document_id,generation_id,family,unit_key,group_key,representation,source_sha256,artifact_bytes,sha256,byte_length,locator)
   values(c.document_id,g,'attempt_control','preseal_checkpoint','control','provenance_json',c.source_sha256,checkpoint_bytes,checkpoint_hash,octet_length(checkpoint_bytes),'ingestion_attempt:admin_pdf_preseal');
  insert into ingestion_generation_evidence.outcomes(document_id,generation_id,family,unit_key,group_key,outcome)
   values(c.document_id,g,'attempt_control','preseal_checkpoint','control',jsonb_build_object('unitId',jsonb_build_object('family','attempt_control','key','preseal_checkpoint'),'groupKey','control','disposition','retained','artifactSha256',checkpoint_hash,'limitation',null));
  insert into ingestion_generation_evidence.prerequisite_accounting(document_id,generation_id,snapshot_digest,snapshot) values(c.document_id,g,h,s);
  insert into public.document_chunks(id,document_id,page_number,chunk_index,section_heading,section_path,heading_level,parent_heading,anchor_id,content,retrieval_synopsis,content_hash,index_generation_id,token_estimate,image_ids,metadata,embedding)
   select id,document_id,page_number,chunk_index,section_heading,section_path,heading_level,parent_heading,anchor_id,content,retrieval_synopsis,content_hash,index_generation_id,token_estimate,image_ids,metadata,embedding from ingestion_generation_evidence.managed_vector_chunk_rows where document_id=c.document_id and index_generation_id=g;
  select jsonb_agg(jsonb_build_object('page_number',page_number,'text',content,'ocr_used',false,'metadata',metadata) order by page_number) into pages from ingestion_generation_evidence.managed_vector_chunk_rows where document_id=c.document_id and index_generation_id=g;
  quality:=jsonb_build_object('quality_score',1,'extraction_quality','good','issues','[]'::jsonb,'metrics',jsonb_build_object('page_count',4,'chunk_count',4,'ocr_page_count',0,'needs_ocr_page_count',0,
   'admin_pdf_seal_digest',h,'scope','labelled four-page native pilot only','private_required_table_crops',1,'public_image_count',0,'optional_enrichment',p->'optionalEnrichment'));
  perform set_config('psychsift.admin_pdf_terminal_owner',c.document_id::text||':'||c.job_id::text,true);
  result:=public.commit_document_index_generation(f,g,4,4,0,'{}'::jsonb,pages,quality);
  if result->'ok' is distinct from 'true'::jsonb then raise exception 'managed_admin_pdf_commit_failed';end if;
  next_fence:=result->'fence';
  result:=public.complete_ingestion_job(next_fence,j.batch_id,'admin_pdf_completed');
  if result->'ok' is distinct from 'true'::jsonb then raise exception 'managed_admin_pdf_completion_failed';end if;
  update public.ingestion_jobs set next_run_at=null,lease_expires_at=null,lease_duration_seconds=null where id=c.job_id;
  perform set_config('psychsift.admin_pdf_terminal_owner','',true);
  replay:='completed';
 end if;
 return jsonb_build_object('ok',true,'managedAdminPdfTerminal',jsonb_build_object('status','admin_pdf_completed','replay',replay,'activated',true,'seal',ingestion_generation_evidence.admin_pdf_ref(bytes)));
end $$;


alter function ingestion_generation_evidence.admin_pdf_blob(jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.admin_pdf_blob(jsonb) from public,anon,authenticated,service_role;

alter function ingestion_generation_evidence.admin_pdf_ref(bytea) owner to postgres;
revoke all on function ingestion_generation_evidence.admin_pdf_ref(bytea) from public,anon,authenticated,service_role;

alter function ingestion_generation_evidence.admin_pdf_fixed_evidence(ingestion_generation_evidence.candidates,jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.admin_pdf_fixed_evidence(ingestion_generation_evidence.candidates,jsonb) from public,anon,authenticated,service_role;

alter function ingestion_generation_evidence.admin_pdf_evaluate(ingestion_generation_evidence.candidates,jsonb,jsonb) owner to postgres;
revoke all on function ingestion_generation_evidence.admin_pdf_evaluate(ingestion_generation_evidence.candidates,jsonb,jsonb) from public,anon,authenticated,service_role;

alter function ingestion_generation_evidence.admin_pdf_commit_allowed(jsonb,uuid) owner to postgres;
revoke all on function ingestion_generation_evidence.admin_pdf_commit_allowed(jsonb,uuid) from public,anon,authenticated,service_role;

alter function ingestion_generation_evidence.complete_admin_pdf(jsonb,uuid,jsonb,boolean) owner to postgres;
revoke all on function ingestion_generation_evidence.complete_admin_pdf(jsonb,uuid,jsonb,boolean) from public,anon,authenticated,service_role;

create or replace function public.complete_managed_admin_text(p_fence jsonb,p_generation uuid,p_packet jsonb,p_read_only boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 c ingestion_generation_evidence.candidates; a jsonb; j public.ingestion_jobs; ad public.document_admission_events;
 original ingestion_generation_evidence.retained_artifacts; witness ingestion_generation_evidence.retained_artifacts;
 retained ingestion_generation_evidence.retained_artifacts; prepared ingestion_generation_evidence.retained_artifacts;
 final ingestion_generation_evidence.retained_artifacts; candidate_row ingestion_generation_evidence.candidate_chunk_rows;
 public_row public.document_chunks; actual jsonb; identity jsonb; w jsonb; g jsonb; u jsonb; r jsonb; b jsonb;
 seal jsonb; prior ingestion_generation_evidence.prerequisite_accounting; source_text text; cursor_byte integer:=0;
 start_byte integer; end_byte integer; chunk_total integer; chunk_index integer:=0; source_covered integer:=0;
 bytes bytea; digest text; pages jsonb; quality jsonb; next_fence jsonb; result jsonb;
begin
 if p_packet->>'version'='managed-admin-pdf-complete-v1' then
  return ingestion_generation_evidence.complete_admin_pdf(p_fence,p_generation,p_packet,p_read_only);
 end if;
 if p_read_only is null or not ingestion_generation_evidence.visual_unit_fence(p_fence)
   or p_fence->>'job_kind' is distinct from 'node' or p_generation is null
   or not ((p_packet->>'version'='managed-admin-text-complete-v1' and ingestion_generation_evidence.keys(p_packet,array['version','identity','chunks','quality']))
     or (p_packet->>'version'='managed-admin-text-complete-v2' and ingestion_generation_evidence.keys(p_packet,array['version','identity','chunks','sections','quality']) and jsonb_typeof(p_packet->'sections')='array'))
   or jsonb_typeof(p_packet->'chunks') is distinct from 'array'
   then raise exception 'managed_admin_text_invalid_packet';end if;
 chunk_total:=jsonb_array_length(p_packet->'chunks');
 if not ingestion_generation_evidence.keys(p_packet->'quality',array['quality_score','extraction_quality','issues','metrics'])
   or jsonb_typeof(p_packet->'quality'->'quality_score') is distinct from 'number'
   or (p_packet->'quality'->>'quality_score')::numeric not between 0 and 1
   or coalesce(p_packet->'quality'->>'extraction_quality','') not in ('good','partial','poor','unknown')
   or jsonb_typeof(p_packet->'quality'->'issues') is distinct from 'array' or jsonb_typeof(p_packet->'quality'->'metrics') is distinct from 'object'
   then raise exception 'managed_admin_text_quality_mismatch';end if;
 if chunk_total<1 or chunk_total>2000 or octet_length(convert_to(p_packet::text,'UTF8'))>1048576
   then raise exception 'managed_admin_text_transport_limit';end if;
 -- Preserve governance -> document -> both sorted job sets -> candidate lock order.
 a:=public.lock_ingestion_document_authority((p_fence->>'document_id')::uuid,false);
 if a is null then raise exception 'managed_admin_text_authority_mismatch';end if;
 perform 1 from public.ingestion_jobs where document_id=(p_fence->>'document_id')::uuid order by id for update;
 perform 1 from public.indexing_v3_agent_jobs where document_id=(p_fence->>'document_id')::uuid order by id for update;
 select * into strict j from public.ingestion_jobs where id=(p_fence->>'job_id')::uuid;
 select * into strict c from ingestion_generation_evidence.candidates
   where document_id=(p_fence->>'document_id')::uuid and generation_id=p_generation for update;
 identity:=jsonb_build_object('documentId',c.document_id,'generationId',c.generation_id,'jobId',c.job_id,
   'workerId',p_fence->>'worker_id','firstLeaseToken',c.first_lease_token,'attemptNumber',j.attempt_count,
   'batchId',j.batch_id,'authorityDigest',c.authority_digest,'predecessorGenerationId',c.predecessor_generation_id,
   'ownerId',c.source_snapshot->'owner_id','sourceSha256',c.source_sha256,'sourceByteLength',c.source_byte_length,
   'sourceExpectationDigest',c.source_expectation_digest);
 if p_packet->'identity' is distinct from identity or j.id is distinct from c.job_id or j.document_id is distinct from c.document_id
   or j.lease_token is distinct from c.first_lease_token or c.first_lease_token::text is distinct from p_fence->>'lease_token'
   or j.lease_write_generation_id is distinct from c.generation_id or c.predecessor_generation_id is distinct from (p_fence->>'expected_generation_id')::uuid
   or c.authority_digest is distinct from p_fence->>'authority_digest' or c.authority_digest is distinct from a->>'authority_digest'
   or j.lease_authority_digest is distinct from c.authority_digest or c.source_snapshot->'owner_id' is distinct from a->'document'->'owner_id'
   or c.source_sha256 is distinct from 'sha256:'||(a->'document'->>'content_hash')
   or c.source_byte_length is distinct from (a->'document'->>'file_size')::bigint or c.source_byte_length>2097152
   or a->'document'->>'file_type' is distinct from 'text/plain'
   or exists(select 1 from public.ingestion_jobs other where other.document_id=c.document_id and other.id<>j.id
     and (other.created_at>j.created_at or other.status in ('pending','processing')))
   then raise exception 'managed_admin_text_identity_mismatch';end if;
 select * into ad from public.document_admission_events where id=(a->'document'->'metadata'->>'admission_event_id')::uuid;
 if not found or ad.actor_kind is distinct from 'administrator' or ad.source_channel is distinct from 'admin_api'
   or ad.document_id is distinct from c.document_id or ad.staging_owner_id is distinct from (a->'document'->>'owner_id')::uuid
   or ad.content_sha256 is distinct from c.source_sha256 or ad.byte_count is distinct from c.source_byte_length or ad.mime_type is distinct from 'text/plain'
   or ad.admission_policy_version is distinct from 'trusted-document-admission-v1'
   or ad.authority is distinct from a->'document'->'metadata'->'authority'
   or c.source_snapshot->'metadata'->'admission_event_id' is distinct from a->'document'->'metadata'->'admission_event_id'
   or ad.authority->>'authorityBasis' is distinct from 'administrator_template'
   or ad.authority->>'licencePolicy' is distinct from 'public_index_permitted'
   or ad.authority->>'providerProcessing' is distinct from 'permitted'
   or ad.authority->>'purpose' is distinct from 'clinical_retrieval'
   or ad.authority->>'currentness' is distinct from 'current' or ad.authority->'supportedFeatures' is distinct from '["text"]'::jsonb
   or (ad.authority->>'effectiveDate')::date>current_date or (ad.authority->>'expiryDate')::date<=current_date
   or (ad.authority->>'reviewDate')::date<=current_date
   then raise exception 'managed_admin_text_admission_mismatch';end if;
 select * into original from ingestion_generation_evidence.retained_artifacts
   where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='original-source';
 if not found or original.representation<>'original_binary' or original.sha256 is distinct from c.source_sha256
   or original.byte_length is distinct from c.source_byte_length or original.byte_length<>octet_length(original.artifact_bytes)
   or original.sha256<>'sha256:'||encode(extensions.digest(original.artifact_bytes,'sha256'),'hex') then raise exception 'managed_admin_text_original_mismatch';end if;
 source_text:=convert_from(original.artifact_bytes,'UTF8');
 if convert_to(source_text,'UTF8')<>original.artifact_bytes or btrim(source_text)='' then raise exception 'managed_admin_text_utf8';end if;
 if p_packet->'quality'->'metrics'->'page_count' is distinct from '1'::jsonb
   or p_packet->'quality'->'metrics'->'ocr_page_count' is distinct from '0'::jsonb
   or p_packet->'quality'->'metrics'->'needs_ocr_page_count' is distinct from '0'::jsonb
   or p_packet->'quality'->'metrics'->'extracted_image_count' is distinct from '0'::jsonb
   or p_packet->'quality'->'metrics'->'searchable_image_count' is distinct from '0'::jsonb
   then raise exception 'managed_admin_text_quality_mismatch';end if;
 select * into witness from ingestion_generation_evidence.retained_artifacts
   where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='original-source-expectation-witness';
 if not found or witness.representation<>'source_expectation_witness' or witness.sha256 is distinct from c.source_expectation->'witness'->>'sha256'
   or witness.source_sha256<>c.source_sha256 or witness.sha256<>'sha256:'||encode(extensions.digest(witness.artifact_bytes,'sha256'),'hex')
   or witness.byte_length<>octet_length(witness.artifact_bytes) or c.source_expectation->>'tag' is distinct from 'known'
   or convert_from(c.source_expectation_bytes,'UTF8')::jsonb is distinct from c.source_expectation
   or c.source_expectation_digest<>'sha256:'||encode(extensions.digest(c.source_expectation_bytes,'sha256'),'hex')
   then raise exception 'managed_admin_text_witness_mismatch';end if;
 w:=convert_from(witness.artifact_bytes,'UTF8')::jsonb;
 if not ingestion_generation_evidence.keys(w,array['version','qualification','sourceSha256','sourceByteLength','sourceUnits','groups'])
   or w->>'version' is distinct from 'ingestion-original-applicability-v1' or w->>'qualification' is distinct from 'independently_declared_unverified'
   or w->>'sourceSha256' is distinct from c.source_sha256 or w->'sourceByteLength' is distinct from to_jsonb(c.source_byte_length)
   or w->'sourceUnits' is distinct from c.source_expectation->'units' or jsonb_typeof(w->'groups') is distinct from 'array'
   or jsonb_array_length(w->'groups')<>5 or (select count(distinct value->>'family') from jsonb_array_elements(w->'groups'))<>5
   then raise exception 'managed_admin_text_original_population_mismatch';end if;
 for g in select value from jsonb_array_elements(w->'groups') loop
   if not ingestion_generation_evidence.keys(g,array['family','population']) or g->>'family' not in ('chunks','images','table_facts','embedding_fields','index_units')
     or not ingestion_generation_evidence.keys(g->'population',array['tag','requirements','basis','reason'])
     or g->'population'->>'tag' is distinct from 'known' or jsonb_typeof(g->'population'->'requirements') is distinct from 'array'
     or g->'population'->'basis' is distinct from '{"scope":"whole_original","kind":"independent_original_declaration"}'::jsonb
     then raise exception 'managed_admin_text_original_population_mismatch';end if;
   if g->>'family'='chunks' then
     if jsonb_array_length(g->'population'->'requirements')=0 or g->'population'->'reason' is distinct from 'null'::jsonb then raise exception 'managed_admin_text_original_population_mismatch';end if;
     if (select count(distinct value->>'id') from jsonb_array_elements(g->'population'->'requirements'))<>jsonb_array_length(g->'population'->'requirements') then raise exception 'managed_admin_text_source_obligation_mismatch';end if;
     for r in select value from jsonb_array_elements(g->'population'->'requirements') loop
       if not ingestion_generation_evidence.keys(r,array['id','required','sourceEvidenceIds']) or r->'required' is distinct from 'true'::jsonb
         or jsonb_typeof(r->'sourceEvidenceIds') is distinct from 'array' or jsonb_array_length(r->'sourceEvidenceIds')<1
         or (select count(distinct value) from jsonb_array_elements(r->'sourceEvidenceIds'))<>jsonb_array_length(r->'sourceEvidenceIds')
         or exists(select 1 from jsonb_array_elements_text(r->'sourceEvidenceIds') ref where not exists(select 1 from jsonb_array_elements(w->'sourceUnits') su where su.value->>'id'=ref))
         or exists(select 1 from jsonb_array_elements(w->'sourceUnits') su cross join lateral jsonb_array_elements_text(su.value->'dependencies') dep
           where r->'sourceEvidenceIds' ? (su.value->>'id') and not (r->'sourceEvidenceIds' ? dep))
         then raise exception 'managed_admin_text_source_obligation_mismatch';end if;
     end loop;
   elsif g->'population'->'requirements'<>'[]'::jsonb or g->'population'->>'reason' is distinct from 'no_original_requirements_in_scope'
     then raise exception 'managed_admin_text_unsupported_original_requirements';end if;
 end loop;
 if jsonb_array_length(w->'sourceUnits')<1 then raise exception 'managed_admin_text_source_coverage_gap';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(w->'sourceUnits'))<>jsonb_array_length(w->'sourceUnits')
   or exists(select 1 from jsonb_array_elements(w->'sourceUnits') su where not ingestion_generation_evidence.keys(su.value,array['id','required','dependencies','locator','nativeMapping'])
     or jsonb_typeof(su.value->'required') is distinct from 'boolean' or jsonb_typeof(su.value->'dependencies') is distinct from 'array' or su.value->>'nativeMapping' is distinct from 'unavailable'
     or exists(select 1 from jsonb_array_elements_text(su.value->'dependencies') dep where not exists(select 1 from jsonb_array_elements(w->'sourceUnits') parent where parent.value->>'id'=dep)))
   then raise exception 'managed_admin_text_source_obligation_mismatch';end if;
 if exists(with recursive edges as (
   select su.value->>'id' as root,su.value->>'id' as node,array[su.value->>'id']::text[] as path,false as cycle from jsonb_array_elements(w->'sourceUnits') su
   union all select edges.root,dep,array_append(edges.path,dep),dep=any(edges.path) from edges join lateral jsonb_array_elements(w->'sourceUnits') su on su.value->>'id'=edges.node cross join lateral jsonb_array_elements_text(su.value->'dependencies') dep where not edges.cycle)
   select 1 from edges where cycle) then raise exception 'managed_admin_text_source_dependency_cycle';end if;
 for u in select value from jsonb_array_elements(w->'sourceUnits') order by split_part(value->>'locator',':',2)::integer,split_part(value->>'locator',':',3)::integer loop
   if coalesce(u->>'locator','') !~ '^utf8-bytes:(0|[1-9][0-9]*):([1-9][0-9]*)$' then raise exception 'managed_admin_text_source_locator';end if;
   start_byte:=split_part(u->>'locator',':',2)::integer;end_byte:=split_part(u->>'locator',':',3)::integer;
   if start_byte>source_covered or start_byte>=end_byte or end_byte>c.source_byte_length then raise exception 'managed_admin_text_source_coverage_gap';end if;
   perform convert_from(substring(original.artifact_bytes from start_byte+1 for end_byte-start_byte),'UTF8');
   source_covered:=greatest(source_covered,end_byte);
   if u->'required'='true'::jsonb and not exists(select 1 from jsonb_array_elements(w->'groups') gr cross join lateral jsonb_array_elements(gr.value->'population'->'requirements') req where gr.value->>'family'='chunks' and req.value->'sourceEvidenceIds' ? (u->>'id')) then raise exception 'managed_admin_text_source_obligation_mismatch';end if;
 end loop;
 if source_covered<>c.source_byte_length then raise exception 'managed_admin_text_source_coverage_gap';end if;
 -- TXT has one exact logical page. Unknown generic native diagnostics are superseded
 -- only for this type by direct original/extracted/persisted UTF8 byte identity.
 for retained in select * from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id loop
   if retained.sha256<>'sha256:'||encode(extensions.digest(retained.artifact_bytes,'sha256'),'hex') or retained.byte_length<>octet_length(retained.artifact_bytes) or retained.source_sha256<>c.source_sha256 then raise exception 'managed_admin_text_retained_mismatch';end if;
 end loop;
 if (select count(*) from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='pages')<>1
   or not exists(select 1 from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='page:1:extracted' and artifact_bytes=original.artifact_bytes and representation='extracted_utf8')
   or not exists(select 1 from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='private_objects' and unit_key='page:1:persisted' and artifact_bytes=original.artifact_bytes and representation='persisted_utf8')
   then raise exception 'managed_admin_text_page_mismatch';end if;
 select convert_from(artifact_bytes,'UTF8')::jsonb into strict b from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='pages' and unit_key='1' and representation='page_projection';
 if b->>'text' is distinct from source_text or b->'page_number' is distinct from '1'::jsonb or b->'ocr_used' is distinct from 'false'::jsonb then raise exception 'managed_admin_text_page_mismatch';end if;
 pages:=jsonb_build_array(b);
 if exists(select 1 from ingestion_generation_evidence.unit_declarations d left join ingestion_generation_evidence.outcomes o using(document_id,generation_id,family,unit_key)
   where d.document_id=c.document_id and d.generation_id=c.generation_id and d.declaration->'required'='true'::jsonb
     and not (d.family='attempt_control' and d.unit_key='preseal_checkpoint')
     and (o.outcome->>'disposition' is distinct from 'retained' or not exists(select 1 from ingestion_generation_evidence.retained_artifacts art where art.document_id=d.document_id and art.generation_id=d.generation_id and art.family=d.family and art.unit_key=d.unit_key and art.sha256=o.outcome->>'artifactSha256')))
   or exists(select 1 from ingestion_generation_evidence.unit_declarations d cross join lateral jsonb_array_elements(d.declaration->'dependencies') dep where d.document_id=c.document_id and d.generation_id=c.generation_id and not exists(select 1 from ingestion_generation_evidence.outcomes o where o.document_id=c.document_id and o.generation_id=c.generation_id and o.family=dep.value->>'family' and o.unit_key=dep.value->>'key' and o.outcome->>'disposition'='retained'))
   then raise exception 'managed_admin_text_required_retention_missing';end if;
 if (select count(*) from ingestion_generation_evidence.candidate_chunk_rows where document_id=c.document_id and index_generation_id=c.generation_id)<>chunk_total
   or (select count(*) from ingestion_generation_evidence.unit_declarations where document_id=c.document_id and generation_id=c.generation_id and family='chunks')<>2*chunk_total
   or exists(select 1 from ingestion_generation_evidence.scoped_projection_rows where document_id=c.document_id and generation_id=c.generation_id)
   or exists(select 1 from ingestion_generation_evidence.visual_unit_rows where document_id=c.document_id and generation_id=c.generation_id)
   or exists(select 1 from ingestion_generation_evidence.unit_declarations where document_id=c.document_id and generation_id=c.generation_id and family not in ('private_objects','pages','chunks','document_metadata','quality','attempt_control') and not (p_packet->>'version'='managed-admin-text-complete-v2' and family='sections'))
   or exists(select 1 from ingestion_generation_evidence.managed_vector_packets where document_id=c.document_id and generation_id=c.generation_id)
   then raise exception 'managed_admin_text_chunk_population_mismatch';end if;
 for r in select value from jsonb_array_elements(p_packet->'chunks') loop
   if not ingestion_generation_evidence.keys(r,array['id','chunkIndex','start','end','sha256'])
     or r->'chunkIndex' is distinct from to_jsonb(chunk_index) or r->'start' is distinct from to_jsonb(cursor_byte)
     or (r->>'end')::integer<=cursor_byte or (r->>'end')::integer>c.source_byte_length then raise exception 'managed_admin_text_chunk_coverage_mismatch';end if;
   select * into strict candidate_row from ingestion_generation_evidence.candidate_chunk_rows where id=(r->>'id')::uuid and document_id=c.document_id and index_generation_id=c.generation_id;
   select * into strict prepared from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='chunks' and unit_key=candidate_row.id::text||':prepared';
   select * into strict final from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='chunks' and unit_key=candidate_row.id::text||':final';
   public_row:=jsonb_populate_record(null::public.document_chunks,to_jsonb(candidate_row));
   actual:=(to_jsonb(public_row)-array['created_at','search_tsv','embedding'])||jsonb_build_object('embedding',(public_row.embedding::text)::jsonb);
   b:=convert_from(final.artifact_bytes,'UTF8')::jsonb;
   if candidate_row.chunk_index<>chunk_index or candidate_row.page_number<>1 or candidate_row.candidate_owner_id is distinct from (identity->>'ownerId')::uuid
     or candidate_row.candidate_job_id<>c.job_id or candidate_row.candidate_lease_token<>c.first_lease_token or candidate_row.candidate_authority_digest<>c.authority_digest
     or candidate_row.candidate_source_sha256<>c.source_sha256 or candidate_row.candidate_source_expectation_digest<>c.source_expectation_digest
     or candidate_row.candidate_prepared_sha256<>prepared.sha256 or candidate_row.embedding is null or jsonb_array_length((candidate_row.embedding::text)::jsonb)<>1536
     or not exists(select 1 from jsonb_array_elements_text((candidate_row.embedding::text)::jsonb) coordinate where coordinate::double precision<>0)
     or candidate_row.image_ids<>'{}'::uuid[] or candidate_row.retrieval_synopsis is not null
     or convert_to(candidate_row.content,'UTF8')<>substring(original.artifact_bytes from cursor_byte+1 for (r->>'end')::integer-cursor_byte)
     or r->>'sha256'<>'sha256:'||encode(extensions.digest(convert_to(candidate_row.content,'UTF8'),'sha256'),'hex')
     or b->'row' is distinct from actual or b->>'preparedSha256' is distinct from prepared.sha256
     or (convert_from(prepared.artifact_bytes,'UTF8')::jsonb)->'row' is distinct from (actual-'embedding')||jsonb_build_object('metadata',(actual->'metadata')-array['ingestion_job_id','ingestion_job_kind','ingestion_lease_token'])
     then raise exception 'managed_admin_text_chunk_readback_mismatch';end if;
   cursor_byte:=(r->>'end')::integer;chunk_index:=chunk_index+1;
 end loop;
 if cursor_byte<>c.source_byte_length then raise exception 'managed_admin_text_chunk_coverage_mismatch';end if;
 select 'sha256:'||encode(extensions.digest(convert_to(jsonb_agg(jsonb_build_object('key',unit_key,'sha256',sha256,'byteLength',byte_length) order by unit_key)::text,'UTF8'),'sha256'),'hex') into digest from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='chunks';
 if p_packet->>'version'='managed-admin-text-complete-v2' then
   if j.status='completed' then
     -- All generations: an old-generation row must not move into the checked population.
     perform 1 from public.document_sections where document_id=c.document_id order by id for share;
     perform 1 from public.document_index_quality where document_id=c.document_id order by document_id for share;
   end if;
   perform ingestion_generation_evidence.assert_admin_text_sections(c,p_packet,j.status='completed');
   if p_packet->'quality' is distinct from ingestion_generation_evidence.admin_text_quality(c,jsonb_array_length(p_packet->'sections')) then raise exception 'managed_admin_text_quality_mismatch';end if;
 end if;
 seal:=jsonb_build_object('version','managed-admin-text-seal-v1','scope','whole_retained_utf8_txt','activated',true,'packet',p_packet,
   'chunkPopulationDigest',digest,'sourceWitnessSha256',witness.sha256,
   'nativeFidelity','whole_original_extracted_persisted_utf8_bytes_equal','sourceCompleteness','whole_original_byte_domain_covered',
   'deferredOptionalFamilies',jsonb_build_array('embedding_fields','index_units','table_facts','images','summary','generated_labels','sections','memory_cards','producer_aliases','cache_inputs'),
   'clinicalApproval','not_assessed','publicationApproval','not_granted');
 if p_packet->>'version'='managed-admin-text-complete-v2' then
   seal:=seal||jsonb_build_object('sectionsVersion','managed-admin-text-sections-v2','deferredOptionalFamilies',(seal->'deferredOptionalFamilies')-'sections');
 end if;
 digest:='sha256:'||encode(extensions.digest(convert_to(seal::text,'UTF8'),'sha256'),'hex');
 if j.status='completed' then
   select * into strict prior from ingestion_generation_evidence.prerequisite_accounting where document_id=c.document_id and generation_id=c.generation_id and snapshot->>'version'='managed-admin-text-seal-v1';
   if prior.snapshot is distinct from seal or prior.snapshot_digest<>digest or j.stage<>'admin_text_completed' or j.locked_by is not null
     or j.lease_expires_at is not null or j.next_run_at is not null or j.lease_expected_generation_id is distinct from c.generation_id
     or (a->'document'->>'index_generation_id')::uuid is distinct from c.generation_id
     or (select count(*) from public.document_chunks where document_id=c.document_id and index_generation_id=c.generation_id)<>chunk_total
     or exists(select 1 from ingestion_generation_evidence.candidate_chunk_rows cr left join public.document_chunks pr on pr.id=cr.id where cr.document_id=c.document_id and cr.index_generation_id=c.generation_id and (pr.id is null or (to_jsonb(pr)-array['created_at','search_tsv']) is distinct from (to_jsonb(jsonb_populate_record(null::public.document_chunks,to_jsonb(cr)))-array['created_at','search_tsv'])))
     or not exists(select 1 from public.document_pages where document_id=c.document_id and index_generation_id=c.generation_id and page_number=1 and text=source_text and not ocr_used)
     or (select count(*) from public.document_pages where document_id=c.document_id and index_generation_id=c.generation_id)<>1
     or exists(select 1 from public.document_images where document_id=c.document_id and index_generation_id=c.generation_id)
     or not exists(select 1 from public.document_index_quality where document_id=c.document_id and owner_id=(identity->>'ownerId')::uuid and quality_score=(p_packet->'quality'->>'quality_score')::real and extraction_quality=p_packet->'quality'->>'extraction_quality' and metrics->>'admin_text_seal_digest'=digest)
     or not exists(select 1 from ingestion_generation_evidence.retained_artifacts art join ingestion_generation_evidence.outcomes o using(document_id,generation_id,family,unit_key) where art.document_id=c.document_id and art.generation_id=c.generation_id and art.family='attempt_control' and art.unit_key='preseal_checkpoint' and o.outcome->>'artifactSha256'=art.sha256 and o.outcome->>'disposition'='retained' and (convert_from(art.artifact_bytes,'UTF8')::jsonb)->'terminalPacket'=p_packet)
     then raise exception 'managed_admin_text_replay_mismatch';end if;
   if p_packet->>'version'='managed-admin-text-complete-v2' then perform ingestion_generation_evidence.assert_admin_text_quality_state(c,p_packet,digest);end if;
   result:=jsonb_build_object('status','admin_text_completed','replay','already_completed','activated',true);
 else
   if p_read_only or j.status<>'processing' or j.locked_by is distinct from p_fence->>'worker_id' or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp()
     or j.lease_expected_generation_id is distinct from c.predecessor_generation_id or (a->'document'->>'index_generation_id')::uuid is distinct from c.predecessor_generation_id
     then raise exception 'managed_admin_text_current_attempt_required';end if;
   if public.assert_current_ingestion_attempt(p_fence,p_generation) is null then raise exception 'managed_admin_text_current_attempt_required';end if;
   -- Generic producers remain unable to mint preseal credit. This terminal alone
   -- retains the server-produced checkpoint at the checked activation boundary.
   select * into strict retained from ingestion_generation_evidence.retained_artifacts where document_id=c.document_id and generation_id=c.generation_id and family='attempt_control' and unit_key='claim_checkpoint';
   b:=convert_from(retained.artifact_bytes,'UTF8')::jsonb;
   if (b-array['version','phase','qualification']) is distinct from (identity-'ownerId') or b->>'version' is distinct from 'ingestion-attempt-control-v1' or b->>'phase' is distinct from 'claim' or b->>'qualification' is distinct from 'derived_unverified'
     or not exists(select 1 from ingestion_generation_evidence.unit_declarations where document_id=c.document_id and generation_id=c.generation_id and family='attempt_control' and unit_key='preseal_checkpoint' and declaration->'dependencies'='[{"family":"attempt_control","key":"claim_checkpoint"},{"family":"private_objects","key":"original-source"}]'::jsonb)
     then raise exception 'managed_admin_text_attempt_control_mismatch';end if;
   b:=b||jsonb_build_object('phase','preseal','terminalVersion','managed-admin-text-complete-v1','terminalPacket',p_packet);
   bytes:=convert_to(b::text,'UTF8');
   insert into ingestion_generation_evidence.retained_artifacts(document_id,generation_id,family,unit_key,group_key,representation,source_sha256,artifact_bytes,sha256,byte_length,locator)
     values(c.document_id,c.generation_id,'attempt_control','preseal_checkpoint','control','provenance_json',c.source_sha256,bytes,'sha256:'||encode(extensions.digest(bytes,'sha256'),'hex'),octet_length(bytes),'ingestion_attempt:admin_text_preseal');
   insert into ingestion_generation_evidence.outcomes(document_id,generation_id,family,unit_key,group_key,outcome)
     values(c.document_id,c.generation_id,'attempt_control','preseal_checkpoint','control',jsonb_build_object('unitId',jsonb_build_object('family','attempt_control','key','preseal_checkpoint'),'groupKey','control','disposition','retained','artifactSha256','sha256:'||encode(extensions.digest(bytes,'sha256'),'hex'),'limitation',null));
   insert into ingestion_generation_evidence.prerequisite_accounting(document_id,generation_id,snapshot_digest,snapshot) values(c.document_id,c.generation_id,digest,seal);
   insert into public.document_chunks(id,document_id,page_number,chunk_index,section_heading,section_path,heading_level,parent_heading,anchor_id,content,retrieval_synopsis,content_hash,index_generation_id,token_estimate,image_ids,metadata,embedding)
     select cr.id,cr.document_id,cr.page_number,cr.chunk_index,cr.section_heading,cr.section_path,cr.heading_level,cr.parent_heading,cr.anchor_id,cr.content,cr.retrieval_synopsis,cr.content_hash,cr.index_generation_id,cr.token_estimate,cr.image_ids,cr.metadata,cr.embedding from ingestion_generation_evidence.candidate_chunk_rows cr where cr.document_id=c.document_id and cr.index_generation_id=c.generation_id;
   if p_packet->>'version'='managed-admin-text-complete-v2' then
     for r in select value from jsonb_array_elements(p_packet->'sections') loop
       b:=r->'body'||jsonb_build_object('id',r->'id','index_generation_id',p_generation,'producer','local-worker','artifact_generation_id',p_generation);
       insert into public.document_sections(id,document_id,owner_id,section_index,heading,heading_path,page_start,page_end,chunk_ids,summary,tags,extraction_quality,index_generation_id,producer,artifact_generation_id,metadata)
         select sr.id,sr.document_id,sr.owner_id,sr.section_index,sr.heading,sr.heading_path,sr.page_start,sr.page_end,sr.chunk_ids,sr.summary,sr.tags,sr.extraction_quality,sr.index_generation_id,sr.producer,sr.artifact_generation_id,sr.metadata from jsonb_populate_record(null::public.document_sections,b) sr;
     end loop;
     perform ingestion_generation_evidence.assert_admin_text_sections(c,p_packet,true);
   end if;
   quality:=p_packet->'quality'||jsonb_build_object('metrics',p_packet->'quality'->'metrics'||jsonb_build_object('source_byte_length',c.source_byte_length,'text_byte_equality',true,'chunk_byte_coverage',true,'chunk_count',chunk_total,'admin_text_seal_digest',digest));
   perform set_config('psychsift.admin_text_terminal_owner',c.document_id::text||':'||c.job_id::text,true);
   -- The immutable terminal receipt and quality row carry the technical proof.
   -- Keep the existing managed metadata-patch refusal intact.
   result:=public.commit_document_index_generation(p_fence,p_generation,1,chunk_total,0,'{}'::jsonb,pages,quality);
   if result->'ok' is distinct from 'true'::jsonb then raise exception 'managed_admin_text_commit_failed';end if;
   next_fence:=result->'fence';
   if p_packet->>'version'='managed-admin-text-complete-v2' then
     -- Terminal-owned quality delta only; generic managed metadata patches still refuse.
     update public.documents set metadata=metadata||jsonb_build_object('extraction_quality',quality->'extraction_quality',
       'index_quality_score',quality->'quality_score','index_quality_issues',quality->'issues','index_quality_metrics',quality->'metrics',
       'section_count',jsonb_array_length(p_packet->'sections'),'memory_card_count',0),updated_at=clock_timestamp() where id=c.document_id;
     if (public.lock_ingestion_document_authority(c.document_id,false))->>'authority_digest' is distinct from c.authority_digest then raise exception 'managed_admin_text_authority_mismatch';end if;
     perform ingestion_generation_evidence.assert_admin_text_quality_state(c,p_packet,digest);
   end if;
   result:=public.complete_ingestion_job(next_fence,j.batch_id,'admin_text_completed');
   if result->'ok' is distinct from 'true'::jsonb then raise exception 'managed_admin_text_completion_failed';end if;
   update public.ingestion_jobs set next_run_at=null,lease_expires_at=null,lease_duration_seconds=null where id=c.job_id;
   perform set_config('psychsift.admin_text_terminal_owner','',true);
   result:=jsonb_build_object('status','admin_text_completed','replay','completed','activated',true);
 end if;
 bytes:=convert_to(seal::text,'UTF8');
 return jsonb_build_object('ok',true,'managedAdminTextTerminal',result||jsonb_build_object('seal',jsonb_build_object('bytesHex',encode(bytes,'hex'),'sha256',digest,'byteLength',octet_length(bytes))));
exception when invalid_text_representation or character_not_in_repertoire or numeric_value_out_of_range then raise exception 'managed_admin_text_invalid_source';
end $$;

create or replace function public.read_ingestion_prepared_supplier_artifacts(p_fence jsonb, p_generation uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  c ingestion_generation_evidence.candidates;
  result jsonb;
  transport_limit constant bigint := 16777216;
begin
 if p_fence->>'version'='managed-admin-pdf-evidence-read-v1' then
  if not ingestion_generation_evidence.keys(p_fence,array['version','fence','expectedPlanDigest'])
   or not ingestion_generation_evidence.visual_unit_fence(p_fence->'fence') then raise exception 'managed_admin_pdf_invalid_fence';end if;
  c:=ingestion_generation_evidence.lock_candidate(p_fence->'fence',p_generation);
  if c is null then return jsonb_build_object('ok',false,'reason','lease_lost');end if;
  result:=ingestion_generation_evidence.read_native_parent_closure(p_fence->'fence',p_generation,p_fence->>'expectedPlanDigest');
  if result->'ok' is distinct from 'true'::jsonb then return result;end if;
  result:=ingestion_generation_evidence.admin_pdf_fixed_evidence(c,result->'managedNativeParentClosure');
  if ingestion_generation_evidence.lock_candidate(p_fence->'fence',p_generation) is null then return jsonb_build_object('ok',false,'reason','lease_lost');end if;
  return jsonb_build_object('ok',true,'managedAdminPdfEvidence',result);
 end if;

  if p_fence->>'version'='managed-native-parent-closure-read-v1' then
    if not ingestion_generation_evidence.keys(p_fence,array['version','fence','expectedPlanDigest'])
      or not ingestion_generation_evidence.visual_unit_fence(p_fence->'fence') then raise exception 'managed_native_parent_closure_invalid_packet';end if;
    return ingestion_generation_evidence.read_native_parent_closure(p_fence->'fence',p_generation,p_fence->>'expectedPlanDigest');
  end if;
    if p_generation is null
    or not ingestion_generation_evidence.keys(p_fence, array['job_kind','job_id','document_id','worker_id','lease_token','expected_generation_id','authority_digest'])
    or p_fence->>'job_kind' is distinct from 'node'
    or coalesce(p_fence->>'worker_id','') = ''
    or coalesce(p_fence->>'authority_digest','') !~ '^sha256:[0-9a-f]{64}$'
    then raise exception 'prepared_supplier_readback_invalid_fence'; end if;
  -- lock_candidate checks current attempt/source authority and the candidate's FIRST lease.
  c := ingestion_generation_evidence.lock_candidate(p_fence, p_generation);
  if c is null then return jsonb_build_object('ok',false,'reason','lease_lost'); end if;
  if coalesce((select sum(octet_length(a.artifact_bytes)::bigint)*2
      from ingestion_generation_evidence.retained_artifacts a
      where a.document_id=c.document_id and a.generation_id=c.generation_id),0) > transport_limit
    then raise exception 'prepared_supplier_readback_transport_limit_exceeded'; end if;
  if exists (
    select 1 from ingestion_generation_evidence.retained_artifacts a
    left join ingestion_generation_evidence.unit_declarations u
      on u.document_id=a.document_id and u.generation_id=a.generation_id
      and u.family=a.family and u.unit_key=a.unit_key
    where a.document_id=c.document_id and a.generation_id=c.generation_id and (
      u.declaration is null or a.group_key is distinct from u.declaration->>'groupKey'
      or a.representation is distinct from u.declaration->>'representation'
      or a.source_sha256 is distinct from c.source_sha256
      or a.byte_length is distinct from octet_length(a.artifact_bytes)::bigint
      or a.sha256 is distinct from 'sha256:'||encode(extensions.digest(a.artifact_bytes,'sha256'),'hex'))
  ) then raise exception 'prepared_supplier_readback_artifact_identity_mismatch'; end if;
  result := jsonb_build_object('ok',true,'managed',true,'preparedSupplierArtifacts',jsonb_build_object(
    'version','ingestion-prepared-supplier-artifacts-v1',
    'identity',jsonb_build_object('documentId',c.document_id,'ownerId',c.source_snapshot->>'owner_id',
      'generationId',c.generation_id,'jobId',c.job_id,'firstLeaseToken',c.first_lease_token,
      'authorityDigest',c.authority_digest,'sourceSha256',c.source_sha256,
      'sourceByteLength',c.source_byte_length,'sourceExpectationDigest',c.source_expectation_digest),
    'inventory',ingestion_generation_evidence.inventory(c),
    'artifacts',coalesce((select jsonb_agg(jsonb_build_object(
      'unitId',jsonb_build_object('family',a.family,'key',a.unit_key),
      'groupKey',a.group_key,'representation',a.representation,
      'sha256',a.sha256,'byteLength',a.byte_length,'locator',a.locator,
      'bytesHex',encode(a.artifact_bytes,'hex')) order by a.family,a.unit_key)
      from ingestion_generation_evidence.retained_artifacts a
      where a.document_id=c.document_id and a.generation_id=c.generation_id),'[]'::jsonb)));
  if octet_length(convert_to(result::text,'UTF8'))::bigint > transport_limit
    then raise exception 'prepared_supplier_readback_transport_limit_exceeded'; end if;
  return result;
end $$;

create or replace function public.commit_document_index_generation(p_fence jsonb, p_generation uuid, p_page_count integer, p_chunk_count integer, p_image_count integer, p_metadata jsonb, p_pages jsonb, p_quality jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_locked jsonb; v_document_id uuid; v_next jsonb; v_result jsonb;
begin
  v_locked := public.assert_current_ingestion_attempt(p_fence, p_generation);
  if v_locked is null then return jsonb_build_object('ok',false,'reason','lease_lost'); end if;
  v_document_id := (p_fence->>'document_id')::uuid;
  if exists(select 1 from ingestion_generation_evidence.candidates where document_id=v_document_id and generation_id=p_generation) and not (ingestion_generation_evidence.admin_text_commit_allowed(p_fence,p_generation) or ingestion_generation_evidence.admin_pdf_commit_allowed(p_fence,p_generation)) then
    return jsonb_build_object('ok',false,'reason','technical_supplier_not_implemented');
  end if;
  if p_fence->>'job_kind' <> 'node' or p_generation is null or p_chunk_count is null or p_image_count is null or p_page_count is null
    or jsonb_typeof(p_pages) is distinct from 'array' or jsonb_typeof(p_quality) is distinct from 'object'
    or p_page_count < 0 or p_page_count > 100000 or p_chunk_count < 0 or p_image_count < 0 or p_chunk_count+p_image_count = 0
    or p_chunk_count <> (select count(*) from public.document_chunks where document_id=v_document_id and index_generation_id=p_generation)
    or p_image_count <> (select count(*) from public.document_images where document_id=v_document_id and index_generation_id=p_generation and searchable)
    or p_page_count <> jsonb_array_length(p_pages) then raise exception 'invalid_ingestion_core_counts'; end if;
  -- Only the reserved generation becomes visible. Earlier committed evidence is retained for later lifecycle work.
  -- Retain previous generations; typed pages become visible only with sole pointer commit.
  insert into public.document_pages(document_id,index_generation_id,page_number,text,ocr_used,metadata)
  select v_document_id,p_generation,r.page_number,r.text,r.ocr_used,coalesce(r.metadata,'{}'::jsonb)
    from jsonb_to_recordset(p_pages) r(page_number integer,text text,ocr_used boolean,metadata jsonb);
  insert into public.document_index_quality(document_id,owner_id,quality_score,extraction_quality,metrics,issues,updated_at)
  values(v_document_id,(v_locked->'document'->>'owner_id')::uuid,(p_quality->>'quality_score')::real,p_quality->>'extraction_quality',
    p_quality->'metrics',array(select jsonb_array_elements_text(p_quality->'issues')),pg_catalog.clock_timestamp())
  on conflict(document_id) do update set
    quality_score=case when p_fence->>'job_kind'='indexing_v3' then public.document_index_quality.quality_score else excluded.quality_score end,
    extraction_quality=case when p_fence->>'job_kind'='indexing_v3' then public.document_index_quality.extraction_quality else excluded.extraction_quality end,
    metrics=case when p_fence->>'job_kind'='indexing_v3' then public.document_index_quality.metrics || excluded.metrics else excluded.metrics end,
    issues=case when p_fence->>'job_kind'='indexing_v3' then array(select distinct x from unnest(public.document_index_quality.issues || excluded.issues) x) else excluded.issues end,
    updated_at=excluded.updated_at;

  update public.ingestion_jobs set lease_expected_generation_id=p_generation where id=(p_fence->>'job_id')::uuid and document_id=v_document_id and p_fence->>'job_kind'='node'
    and locked_by=p_fence->>'worker_id' and lease_token=(p_fence->>'lease_token')::uuid and status='processing'
    and lease_expected_generation_id is not distinct from (p_fence->>'expected_generation_id')::uuid
    and lease_authority_digest=p_fence->>'authority_digest' and lease_expires_at > pg_catalog.clock_timestamp();
  if not found then raise exception 'ingestion_mutation_row_count'; end if;
  perform set_config('psychsift.page_commit_owner',v_document_id::text,true);
  update public.documents set page_storage_mode='typed_exact',status='indexed',page_count=p_page_count,chunk_count=p_chunk_count,image_count=p_image_count,error_message=null,
    metadata=metadata || jsonb_build_object('index_generation_id',p_generation), updated_at=pg_catalog.clock_timestamp() where id=v_document_id;
  perform set_config('psychsift.page_commit_owner','',true);
  v_next := p_fence || jsonb_build_object('expected_generation_id',p_generation);
  v_result := public.patch_ingestion_document_state(v_next,'{}'::jsonb,p_metadata);
  if v_result->'ok' is distinct from 'true'::jsonb then raise exception 'ingestion_mutation_row_count'; end if;
  return jsonb_build_object('ok',true,'fence',v_next,'index_generation_id',p_generation);
end $$;

create or replace function public.complete_ingestion_job(p_fence jsonb, p_batch_id uuid, p_stage text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_locked jsonb; v_document_id uuid; v_batch uuid; v_pending integer; v_processing integer; v_failed integer;
begin
  if p_fence->>'expected_generation_id' is null then raise exception 'ingestion_attempt_required'; end if;
  v_locked := public.assert_current_ingestion_attempt(p_fence, (p_fence->>'expected_generation_id')::uuid);
  if v_locked is null then return jsonb_build_object('ok',false,'reason','lease_lost'); end if;
  if exists(select 1 from ingestion_generation_evidence.candidates where document_id=(p_fence->>'document_id')::uuid and job_id=(p_fence->>'job_id')::uuid) and not (ingestion_generation_evidence.admin_text_commit_allowed(p_fence,(p_fence->>'expected_generation_id')::uuid) or ingestion_generation_evidence.admin_pdf_commit_allowed(p_fence,(p_fence->>'expected_generation_id')::uuid)) then return jsonb_build_object('ok',false,'reason','technical_supplier_not_implemented'); end if;
  v_document_id := (p_fence->>'document_id')::uuid;
  v_batch := (v_locked->'job'->>'batch_id')::uuid;
  if p_batch_id is not null and p_batch_id is distinct from v_batch then raise exception 'ingestion_batch_identity_mismatch'; end if;
  if v_batch is not null then perform 1 from public.import_batches where id=v_batch for update; end if;
  update public.ingestion_jobs set status='completed',stage=p_stage,progress=100,error_message=null,locked_by=null,locked_at=null,completed_at=pg_catalog.clock_timestamp()
  where id=(p_fence->>'job_id')::uuid and document_id=v_document_id and p_fence->>'job_kind'='node'
    and locked_by=p_fence->>'worker_id' and lease_token=(p_fence->>'lease_token')::uuid and status='processing'
    and lease_expected_generation_id is not distinct from (p_fence->>'expected_generation_id')::uuid
    and lease_authority_digest=p_fence->>'authority_digest' and lease_expires_at > pg_catalog.clock_timestamp();
  if not found then raise exception 'ingestion_mutation_row_count'; end if;
  -- The document and its attempt rows are locked by assert_current_ingestion_attempt.
  -- A successful replacement supersedes older failed attempts, never a newer job.
  update public.ingestion_jobs set status='completed',stage='superseded by successful index',progress=100,
    error_message=null,locked_by=null,locked_at=null,next_run_at=null,completed_at=pg_catalog.clock_timestamp()
  where document_id=v_document_id and id<>(p_fence->>'job_id')::uuid and status='failed'
    and created_at <= (v_locked->'job'->>'created_at')::timestamptz;
  if v_batch is not null then
    select count(*) filter(where status='pending'),count(*) filter(where status='processing'),count(*) filter(where status='failed')
      into v_pending,v_processing,v_failed from public.ingestion_jobs where batch_id=v_batch;
    update public.import_batches set status=case when v_pending+v_processing>0 then 'processing' when v_failed>0 then 'completed_with_errors' else 'completed' end,
      failed_files=v_failed, completed_at=case when v_pending+v_processing>0 then null else pg_catalog.clock_timestamp() end where id=v_batch;
  end if;
  return jsonb_build_object('ok',true);
end $$;
